/* A8 hand-authored depth patch: avouch–bedlam, fixed list of 80 lemmas. */
(function (global) {
'use strict';
const D = global.RA.D;
const q = (w,n,s,p,a,b,c,x) => ({id:w+'.q'+n,senseId:w+'.s'+s,errorType:'meaning',type:'辨义与用法',prompt:p,options:[a,b,c],answer:a,explain:x});
const m = (wrong,right,reason) => ({errorType:'meaning',wrong,right,reason});
const c = (senseId,domain,en,zh,structure,grammar,rationale) => ({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
D('avouch',{
  etymology:{origin:'avouch 约14世纪经 Anglo-French avouchen、古法语 avochier 进入英语，词源与拉丁语 advocare「召来、请作证」有关；与 vouch 同族。',prefix:null,root:null,suffix:null,history:[],formationLogic:null,mnemonic:null,note:'现为较旧、正式的动词，意为郑重断言或保证。',source:'Etymonline — https://www.etymonline.com/word/avouch'},
  contexts:[c('avouch.s1','书面 · 证言','The archivist avouched that the signature belonged to the mayor, citing three dated letters rather than relying on memory.','档案管理员郑重断言签名出自市长，并引用三封带日期的信，而不是凭记忆判断。','The archivist / avouched that the signature belonged to the mayor / citing three dated letters / rather than relying on memory.','that 引导 avouch 的宾语从句；citing 分词短语说明断言的依据。','avouch that introduces a confident assertion; citing documentary evidence makes the claim verifiable, not merely a promise.'),c('avouch.s1','书面 · 担保','The witness was willing to avouch the accuracy of the transcript, but she would not certify the unsigned copy.','证人愿意保证誊本准确无误，但不愿为那份未签名的副本作认证。','The witness / was willing to avouch the accuracy of the transcript / but she would not certify the unsigned copy.','be willing to 后接动词原形；but 连接让步对照。','Here avouch means to assert or vouch for the truth of a document; the refusal concerns a separate, unsigned copy.')],
  mistakes:[m('The witness avouched that the transcript was accurate, then admitted that she had no reason to believe it.','The witness avouched that the transcript was accurate, citing the signed original.','avouch 是有把握地断言或保证；紧接着承认毫无依据会使这个郑重断言失去根据。')],
  quiz:[q('avouch',1,1,'A witness who avouches a statement does what?','asserts it firmly as true','quietly withdraws it','translates it into another language','avouch 指郑重断言或保证某事属实。'),q('avouch',2,1,'Which object can naturally follow “avouch”?','that the figures are correct','under the table','three kilometres tall','avouch 可接 that 从句陈述所保证的内容。'),q('avouch',3,1,'The source labels avouch as which part of speech?','a verb','an adjective','a countable noun only','源词条将 avouch 标为动词。'),q('avouch',4,1,'In a formal report, “I avouch the record” most nearly means?','I firmly vouch for the record','I erase the record','I postpone reading the record','avouch 与 vouch 同族，表示保证、担保其真实性。')]});
D('avow',{
  etymology:{origin:'avow 经盎格鲁法语 avouer、古法语 avouer「承认、认可」进入英语；其更早形式与拉丁语 advocare「召来作证」有关。',prefix:null,root:null,suffix:null,history:[],formationLogic:null,mnemonic:null,note:'现代 avow 常带公开、郑重承认或表明立场之意。',source:'Etymonline — https://www.etymonline.com/word/avow'},
  contexts:[c('avow.s1','职场 · 承认','After the audit exposed the missing entry, the treasurer avowed that she had entered the payment under the wrong account.','审计查出那笔漏记款项后，财务主管承认自己把付款记到了错误的账户下。','After the audit exposed the missing entry / the treasurer / avowed that she had entered the payment under the wrong account.','After 引导时间状语从句；that 从句作 avowed 的宾语；过去完成时表示更早的记账行为。','avow is a forthright admission here: she openly accepts responsibility for the accounting error.'),c('avow.s2','信仰 · 立场','At the ceremony, each delegate avowed loyalty to the constitution and promised to defend its peaceful transfer of power.','仪式上，每位代表都宣誓效忠宪法，并承诺维护其和平移交权力的原则。','At the ceremony / each delegate / avowed loyalty to the constitution / and promised to defend its peaceful transfer of power.','avow loyalty to 是固定搭配；promise to defend 与 avowed 并列。','This sense is a formal declaration of allegiance to a belief or cause, rather than admission of a mistake.')],
  mistakes:[m('At the swearing-in, the delegate avowed loyalty against the constitution and promised to uphold it.','At the swearing-in, the delegate avowed loyalty to the constitution and promised to uphold it.','表示效忠的对象用 loyalty to；against 与“宣誓维护”矛盾。')],
  quiz:[q('avow',1,1,'An employee avows that she made an error. She?','openly admits making it','denies that it happened','asks someone else to calculate it','avow 的第一义是公开承认某事为真。'),q('avow',2,2,'A delegate who avows loyalty is declaring?','formal allegiance to a cause','a wish to leave the group','a private doubt about every rule','第二义是正式宣告忠于信仰或事业。'),q('avow',3,2,'Which phrase matches the source entry?','avow one’s faith','avow at a faith','avow faithfulness with','源词条例句使用 avow one’s faith。'),q('avow',4,1,'Compared with a casual “admit,” avow often sounds?','more formal and deliberate','more like a physical movement','exclusively humorous','avow 通常语气更正式、郑重。')]});
D('awfully',{
  etymology:{origin:'awfully 由形容词 awful 加副词后缀 -ly 构成；awful 本由 awe「敬畏」与 -ful 构成，早期表示令人敬畏，后来发展出「极坏」义。',prefix:null,root:{text:'awe',gloss:'敬畏'},suffix:{text:'-ly',gloss:'构成副词'},history:[],formationLogic:'awful + -ly；口语中常由「非常」加强语气。',mnemonic:null,note:'语义由「可怕地」扩展出非正式程度副词「非常」。',source:'Etymonline — https://www.etymonline.com/word/awfully'},
  contexts:[c('awfully.s1','会话 · 程度','I am awfully grateful that you stayed late to help us label the samples before the courier arrived.','非常感谢你加班帮我们给样本贴好标签，赶在快递员到达前完成。','I / am awfully grateful / that you stayed late / to help us label the samples / before the courier arrived.','awfully 修饰形容词 grateful；that 引导补语从句；to help 表目的。','The positive adjective grateful selects the informal intensifier sense “very”; nothing in the sentence is terrible.'),c('awfully.s2','评价 · 表现差','The orchestra played awfully during the rehearsal because several musicians had received the wrong score.','排练时乐团演奏得糟透了，因为几位乐手拿错了乐谱。','The orchestra / played awfully during the rehearsal / because several musicians had received the wrong score.','awfully 作方式副词修饰 played；because 引导原因从句。','The poor performance and wrong scores establish the literal negative sense “badly,” unlike awfully grateful.')],
  mistakes:[m('She was awfully delighted by the gift, meaning that the present frightened her.','She was awfully delighted by the gift, meaning that she was extremely pleased.','awfully 修饰正面形容词時常是口语程度副词「非常」，不能机械理解为「可怕地」。')],
  quiz:[q('awfully',1,1,'“We are awfully pleased with the result” means we are?','extremely pleased','frightened by the result','slightly uncertain','awfully 可作非正式程度副词，修饰 pleased 表「非常」。'),q('awfully',2,2,'If a player performs awfully, the performance is?','very poor','brilliantly controlled','not yet begun','awfully 的另一义是「糟糕地」。'),q('awfully',3,1,'In “awfully kind,” awfully modifies?','the adjective kind','a noun naming a person','the past tense of a verb','awfully 放在形容词 kind 前，表示程度很高。'),q('awfully',4,2,'Which sentence clearly uses the negative manner sense?','The team defended awfully and conceded four goals.','I am awfully glad you called.','She was awfully kind to the new student.','失四球的防守语境表明 awfully 意为表现糟糕。')]});
D('awhile',{
  etymology:{origin:'awhile 在中古英语中由 a while 连写而来；a 在这里保留古英语/中古英语短语中的「一段时间」用法，整体作副词。',prefix:null,root:null,suffix:null,history:[],formationLogic:null,mnemonic:null,note:'副词 awhile 可直接修饰动词；介词 for 后应写 a while 两词。',source:'Etymonline — https://www.etymonline.com/word/awhile'},
  contexts:[c('awhile.s1','日常 · 短暂停留','The curator asked us to wait awhile in the lobby while she checked whether the conservation room was safe to enter.','馆长让我们在大厅等一会儿，同时她去确认修复室是否可以安全进入。','The curator / asked us to wait awhile in the lobby / while she checked / whether the conservation room was safe to enter.','ask someone to do；awhile 直接修饰 wait；while 引导同时发生的动作。','awhile is the adverb “for a short time,” placed directly after wait; the sentence does not use a preceding for.'),c('awhile.s1','日常 · 暂停','After the final bell, the students sat awhile beneath the covered entrance until the rain eased.','最后一声铃响后，学生们在有顶棚的入口下坐了一会儿，直到雨势减弱。','After the final bell / the students / sat awhile beneath the covered entrance / until the rain eased.','After 作时间状语；sat 后用副词 awhile；until 引导时间从句。','The short duration of sitting is expressed by the adverb awhile, not by a noun phrase with for.')],
  mistakes:[m('The hikers rested for awhile beside the stream before continuing uphill.','The hikers rested for a while beside the stream before continuing uphill.','for 后需名词短语 a while；awhile 是副词，不能接在介词 for 后。')],
  quiz:[q('awhile',1,1,'“Stay awhile” asks someone to stay?','for a short time','until next year','without stopping ever','awhile 作副词，意为一会儿、片刻。'),q('awhile',2,1,'Which form is standard after the preposition for?','for a while','for awhile','for a whilely','介词 for 后用名词短语 a while，分开写。'),q('awhile',3,1,'Choose the standard sentence.','Please sit awhile until the meeting begins.','Please sit for awhile until the meeting begins.','Please awhile sit for until the meeting begins.','sit 后可直接接副词 awhile 修饰动作。'),q('awhile',4,1,'In “They chatted awhile,” awhile functions as?','an adverb of duration','a plural noun','a conjunction meaning although','awhile 修饰 chatted，说明交谈持续了一小段时间。')]});
D('awkwardly',{
  etymology:{origin:'awkwardly 由 awkward 加 -ly 构成；awkward 的早期形式含 awk「方向错误、笨拙」及 -ward「朝……方向」成分，后来发展出社交上的不自在义。',prefix:null,root:null,suffix:{text:'-ly',gloss:'构成副词'},history:[],formationLogic:'awkward + -ly',mnemonic:null,note:'动作义和社交尴尬义都由副词形式表达，需依据所修饰的动作判断。',source:'Etymonline — https://www.etymonline.com/word/awkwardly'},
  contexts:[c('awkwardly.s1','动作 · 搬运','Because the crate was wider than the doorway, Mateo awkwardly tilted it onto one corner and edged it through without scraping the frame.','由于木箱比门口宽，马特奥笨拙地把它倾斜到一个角上，再一点点挪过去，避免刮到门框。','Because the crate was wider than the doorway / Mateo / awkwardly tilted it onto one corner / and edged it through / without scraping the frame.','Because 引导原因；tilted 与 edged 并列；without 后接动名词。','The narrow doorway forces an ungainly physical movement, so awkwardly describes clumsy handling.'),c('awkwardly.s2','社交 · 回应','When the chairperson asked about the unexplained delay, the contractor smiled awkwardly and looked toward the project manager.','主席问起那次原因不明的延误时，承包商尴尬地笑了笑，并看向项目经理。','When the chairperson asked about the unexplained delay / the contractor / smiled awkwardly / and looked toward the project manager.','When 引导时间从句；smiled 与 looked 并列；awkwardly 修饰 smiled。','The uncomfortable question and evasive glance indicate social embarrassment rather than poor physical skill.')],
  mistakes:[m('The dancer awkwardly completed the effortless, perfectly balanced turn with complete grace.','The dancer gracefully completed the effortless, perfectly balanced turn with complete grace.','完美平衡且有风度的旋转与「笨拙地」不符；改为 gracefully 才与描述一致。')],
  quiz:[q('awkwardly',1,1,'A person carrying a sofa through a narrow stairwell may move?','awkwardly because the space restricts movement','awkwardly because the route is perfectly open','awkwardly because they are dancing elegantly','空间狭窄导致动作不灵活，符合 awkwardly 的笨拙义。'),q('awkwardly',2,2,'After an embarrassing question, someone may smile awkwardly because they feel?','socially uncomfortable','physically weightless','certain that nothing unusual happened','第二义描述社交上的尴尬或不自在。'),q('awkwardly',3,1,'Which verb fits the clumsy-motion sense best?','maneuvered the heavy cabinet awkwardly','answered the personal question awkwardly','smiled at the host awkwardly','maneuvered 重柜子直接呈现动作上的笨拙。'),q('awkwardly',4,2,'A pause after an unintended insult would most likely be described as?','awkward','weightless','mechanical','令人不自在的停顿可称 awkward，awkwardly 则修饰其发生方式。')]});
D('axe',{
  etymology:{origin:'axe 是古英语 æx 的延续，见于古日耳曼语同源形式；更早的印欧语词根重建并不确定，因此不再强行拆分。',prefix:null,root:null,suffix:null,history:[],formationLogic:null,mnemonic:null,note:'英式常写 axe，美式也常写 ax；两种拼法均正确。',source:'Etymonline — https://www.etymonline.com/word/axe'},
  contexts:[c('axe.s1','工具 · 伐木','Before the trail crew could move the fallen trunk, Lena used an axe to remove the smaller branches blocking the path.','步道维护队搬动倒下的树干前，莉娜用斧头砍掉了挡路的小树枝。','Before the trail crew could move the fallen trunk / Lena / used an axe / to remove the smaller branches / blocking the path.','use an axe to do 表示用斧头做某事；blocking 分词修饰 branches。','axe is a countable chopping tool here; the timber and cut branches set the concrete tool sense.'),c('axe.s2','媒体 · 大幅取消','Facing a budget shortfall, the council axed the evening bus service but kept the route’s morning departures.','由于预算短缺，市政委员会砍掉了晚间公交服务，但保留了这条线路的早班车。','Facing a budget shortfall / the council / axed the evening bus service / but kept the route’s morning departures.','Facing 分词短语表原因；axed 与 kept 并列对照。','As a verb, axe means abruptly abolish or cut; contrasting retained morning trips shows the targeted reduction.')],
  mistakes:[m('The council axed the route, but it continued operating every evening without any reduction.','The council axed the evening service, but it continued operating every morning.','axe 作动词表示取消或大幅削减；原句“取消”与“每天晚间照常运营”矛盾。')],
  quiz:[q('axe',1,1,'A woodcutter uses an axe to?','chop wood with a heavy blade','measure air pressure','sew cloth loosely','axe 的名词义是带长柄和重刀刃的砍伐工具。'),q('axe',2,2,'If a company axes a project, it?','cancels or sharply cuts it','moves it to a larger building','publishes it unchanged','axe 作动词表示突然取消或大幅削减。'),q('axe',3,1,'Which spelling is also common in American English?','ax','axis','aks','美式英语中 ax 也是 axe 的常见拼法。'),q('axe',4,2,'“The editor axed two pages” means the editor?','removed two pages from the plan or text','added two pages to the final text','bound the pages into a book','编辑把两页删掉，体现动词 axe 的删减义。')]});
D('axle',{
  etymology:{origin:'axle 是 axle-tree 的缩略形式；axle-tree 中 axle 对应古英语 eax「轴」，tree 原指木轴或横木，之后 axle 独立表示车轮转动所依附的轴。',prefix:null,root:null,suffix:null,history:[],formationLogic:null,mnemonic:null,note:'axle 指车轮的机械轴；axis 常指几何轴线或中心轴，二词不可互换。',source:'Etymonline — https://www.etymonline.com/word/axle'},
  contexts:[c('axle.s1','机械 · 车辆','The mechanic found a hairline crack in the rear axle, so she kept the delivery van off the road until the replacement arrived.','技师发现后轴有一道细微裂纹，于是在替换件送到前让送货车停驶。','The mechanic / found a hairline crack in the rear axle / so she kept the delivery van off the road / until the replacement arrived.','so 连接结果；keep + 宾语 + 介词短语；until 引导时间状语。','The rear axle is the vehicle component that supports or connects rotating wheels, and damage makes the van unsafe to drive.'),c('axle.s1','机械 · 车轮','Grease was applied to the axle where the wheel rotated, reducing friction during the test run.','技师在车轮转动所依附的轴上涂了润滑脂，以减少试运行时的摩擦。','Grease / was applied to the axle / where the wheel rotated / reducing friction during the test run.','被动语态 was applied；where 引导地点从句；reducing 作结果补充。','The relative location clause identifies the axle as the bar on which the wheel rotates.')],
  mistakes:[m('The mechanic replaced the car’s axle because the vehicle’s front wheel rotated around the wrong spelling of a coordinate line.','The mechanic replaced the car’s axle because the vehicle’s front wheel rotated around a damaged shaft.','車轮转动所依附的零件叫 axle；axis 是抽象轴线或中心线，不表示汽车零件。')],
  quiz:[q('axle',1,1,'A vehicle axle is most directly connected with?','the wheels that rotate on or around it','the line dividing a paragraph','a tool used to chop wood','axle 是车轮转动所依附或相连的杆轴。'),q('axle',2,1,'A cracked rear axle should concern a mechanic because it is?','a structural vehicle part','a colour of paint','a kind of woven fabric','axle 属于车辆机械结构。'),q('axle',3,1,'Which spelling names the car part?','axle','axe','axel','axle 是车轴；axe 是斧头。'),q('axle',4,1,'In “the wheel turns on its axle,” axle means?','the bar supporting the wheel’s rotation','the road’s centre marking','the driver’s steering wheel','句子把 axle 用作车轮转动的机械轴。')]});
D('azure',{
  etymology:{origin:'azure 经古法语 azur、拉丁语 lazurium 及阿拉伯语 lāzaward 传入英语；更早可追溯至波斯语 lāžward「青金石」，词首 l 在借入时脱落。',prefix:null,root:null,suffix:null,history:[],formationLogic:null,mnemonic:null,note:'词色名与青金石贸易有关；这里不表示普通的任何蓝色。',source:'Etymonline — https://www.etymonline.com/word/azure'},
  contexts:[c('azure.s1','视觉 · 天空','By noon the storm clouds had cleared, leaving an unbroken field of azure above the white cliffs.','到中午，乌云散去，白色峭壁上方只剩一整片碧蓝天空。','By noon / the storm clouds had cleared / leaving an unbroken field of azure / above the white cliffs.','过去完成时说明散云先于结果；leaving 分词短语表示结果。','Azure as a noun names the vivid blue colour or sky; the open sky supplies the colour reference.'),c('azure.s2','描写 · 颜色','The painter chose an azure glaze for the bowl, a bright blue that remained clear after firing.','画家为这只碗选了天蓝色釉料，烧制后仍呈现明亮清澈的蓝色。','The painter / chose an azure glaze for the bowl / a bright blue / that remained clear after firing.','同位语 a bright blue 解释 azure；that 引导定语从句。','Azure modifies glaze adjectivally here and describes a bright, clear blue tone.')],
  mistakes:[m('The artist painted the cloudless midday sky azure, a vivid shade of muddy brown.','The artist painted the cloudless midday sky azure, a vivid shade of clear blue.','azure 指明亮的蓝色，不能同时释作浑浊的棕色。')],
  quiz:[q('azure',1,1,'An azure sky is?','bright blue','muddy brown','colourless black','azure 的名词义可指晴空的鲜明蓝色。'),q('azure',2,2,'In “an azure glaze,” azure functions as?','an adjective describing a vivid blue colour','a verb meaning to heat a bowl','a noun meaning a pottery wheel','该短语中 azure 修饰 glaze，描述其颜色。'),q('azure',3,1,'Which historical object is linked to the word’s origin?','lapis lazuli','a wooden axle','a wool blanket','azure 的词源经阿拉伯语、波斯语与青金石名称有关。'),q('azure',4,2,'A clear azure pool would look?','bright blue','dark green with no blue','red and dusty','azure 表示明亮、清澈的蓝色。')]});
D('babble',{
  etymology:{origin:'babble 是拟声词，约13世纪出现，模仿婴儿含混重复的发声；同类重复音节在多种语言中都用来表现无意义的喋喋声。',prefix:null,root:null,suffix:null,history:[],formationLogic:null,mnemonic:null,note:'可作动词表示含混快说，也可作名词指含混话语、持续声响。',source:'Etymonline — https://www.etymonline.com/word/babble'},
  contexts:[c('babble.s1','语言 · 兴奋交谈','When the doors opened, the excited children began to babble about the field trip, each trying to describe a different animal at once.','门一打开，兴奋的孩子们便叽叽喳喳地谈起郊游，每个人都想同时描述不同的动物。','When the doors opened / the excited children / began to babble about the field trip / each trying to describe a different animal at once.','begin to 后接原形；about 引出谈论主题；each trying 为独立主格补充说明。','The overlapping, rapid speech is hard to follow, matching the verb sense “talk quickly and confusedly.”'),c('babble.s2','声音 · 溪流','From the footbridge, we could hear the gentle babble of the stream beneath the reeds.','站在小桥上，我们能听见芦苇下溪水轻柔的潺潺声。','From the footbridge / we could hear / the gentle babble of the stream / beneath the reeds.','hear 后接宾语；of 短语说明声音来源；beneath 表位置。','The quiet stream rather than human speech makes babble a continuous soft sound.')],
  mistakes:[m('The committee spoke one at a time in clear, measured sentences, so the room was filled with confused babble.','The committee spoke one at a time in clear, measured sentences, so the room was filled with orderly discussion.','轮流、清楚地发言不构成含混杂乱的 babble，改为 orderly discussion 与场景一致。')],
  quiz:[q('babble',1,1,'A toddler babbling is most likely?','making rapid, not fully clear sounds','reading a prepared legal statement','remaining completely silent','babble 可描述婴儿或兴奋者含混快速地说话。'),q('babble',2,2,'The babble of a brook is?','a soft continuous water sound','a written list of expenses','a single loud explosion','babble 作名词也可指溪流持续的轻柔声响。'),q('babble',3,1,'Which sentence uses the verb sense?','The fans babbled excitedly about the final.','The brook babbled over the stones.','The report babbled on the desk.','fans 叽喳谈论比赛，使用动词 babble 的说话义。'),q('babble',4,2,'A room of people speaking over one another may contain?','a confused babble of voices','a measured silence','a single clear announcement','多人同时含混交谈可形成 babble of voices。')]});
D('babelism',{
  etymology:{origin:'babelism 是由专名 Babel（巴别塔故事中语言混乱之地）加 -ism 构成的罕用名词，用来指语言、声音或意见混杂的状态。',prefix:null,root:{text:'Babel',gloss:'巴别塔；语言混乱的典故'},suffix:{text:'-ism',gloss:'状态或现象名词后缀'},history:[],formationLogic:'Babel + -ism；专名典故转为普通名词。',mnemonic:null,note:'这是罕见词；日常表达通常用 confusion 或 cacophony。',source:'Etymonline — https://www.etymonline.com/word/babelism'},
  contexts:[c('babelism.s1','语言 · 多语会议','Without interpreters, the multilingual assembly dissolved into babelism: delegates repeated proposals in several languages, and no shared version emerged.','没有口译员，多语种大会陷入语言混乱：代表们用几种语言反复提出方案，却没有形成共同版本。','Without interpreters / the multilingual assembly / dissolved into babelism / delegates repeated proposals in several languages / and no shared version emerged.','冒号引出 babelism 的具体表现；and 连接并列结果。','The lack of interpreters and absence of a common understanding make babelism a clash of languages rather than ordinary lively conversation.'),c('babelism.s1','讨论 · 意见混杂','The public hearing became babelism when every speaker shouted a different demand and the chair could not identify a single agreed proposal.','每位发言者都在喊不同诉求、主席无法归纳出任何一致方案时，这场听证会变成一片混乱。','The public hearing / became babelism / when every speaker shouted a different demand / and the chair could not identify a single agreed proposal.','when 从句说明转变条件；and 连接从句内两个并列谓语。','The competing opinions and failure to establish a proposal exemplify babelism’s figurative confusion.')],
  mistakes:[m('The translators delivered one consistent bilingual text, so the meeting was a perfect example of babelism.','The translators delivered one consistent bilingual text, so the meeting avoided babelism.','清楚一致的双语文本消除了语言混乱；它不是 babelism 的例子。')],
  quiz:[q('babelism',1,1,'A conference without translation, where nobody understands the competing speeches, shows?','babelism','a unanimous agreement','a quiet intermission','babelism 指多种语言或意见混杂而无法沟通的状态。'),q('babelism',2,1,'Why does the word refer to confusion?','It alludes to the Babel story of confused languages.','It names an ancient measuring instrument.','It comes from a word for a clear translation.','该词借用巴别塔故事中语言混乱的典故。'),q('babelism',3,1,'Which setting best fits the rare noun babelism?','a chaotic multilingual debate','a carefully edited single-language notice','a silent reading room','多语种争论陷入混乱最符合词义。'),q('babelism',4,1,'In everyday prose, which word is usually more common?','confusion','babelism','baberism','babelism 罕用，日常语境常用 confusion。')]});
D('baboon',{
  etymology:{origin:'baboon 约15世纪经古法语 babouin 进入英语；该法语词源的更早来源不确定，词源辞典不支持把它拆成英语词根。',prefix:null,root:null,suffix:null,history:[],formationLogic:null,mnemonic:null,note:'动物名；比喻称人时带侮辱性。',source:'Etymonline — https://www.etymonline.com/word/baboon'},
  contexts:[c('baboon.s1','动物 · 野生观察','At dawn, the guide spotted a baboon sitting on a boulder while the troop searched the dry grassland for roots and seeds.','黎明时，向导发现一只狒狒坐在巨石上，而群体正在干燥的草原上寻找根茎和种子。','At dawn / the guide / spotted a baboon sitting on a boulder / while the troop searched the dry grassland / for roots and seeds.','spot + 宾语 + 现在分词；while 表示同时发生的动作。','The troop, grassland foraging, and animal observation identify baboon as the African primate.'),c('baboon.s2','口语 · 贬义比喻','The coach called the heckler a baboon, a rude insult that made the crowd focus on the coach’s behavior instead.','教练把起哄者骂作粗野的家伙；这是句冒犯性的辱骂，反而让观众注意起教练的行为。','The coach / called the heckler a baboon / a rude insult / that made the crowd focus on the coach’s behavior instead.','call + 宾语 + 名词补语；that 从句修饰 insult。','Calling a person a baboon compares them to an uncivilized animal and is explicitly insulting, unlike neutral zoological use.')],
  mistakes:[m('The wildlife report identified the baboon as a harmless domestic house cat living in the troop.','The wildlife report identified the baboon as a primate living in the troop.','baboon 是大型猴类灵长动物，不是家猫；改成 primate 才符合动物分类。')],
  quiz:[q('baboon',1,1,'A baboon in a wildlife documentary is?','a large African monkey with a long face','a small household cat','a flightless water bird','baboon 指非洲的大型猴类，面部较长。'),q('baboon',2,2,'Calling someone a baboon is usually?','an insulting comparison with a rude person','a formal compliment about their patience','a neutral job title','比喻称人 baboon 带贬义。'),q('baboon',3,1,'A troop of baboons is most likely observed?','foraging together in a grassland','building a nest under the ocean','operating a city bus','baboon 是群居的野生灵长类动物，场景应符合其栖息和觅食。'),q('baboon',4,1,'Which animal group contains baboons?','primates','insects','mollusks','狒狒属于灵长目。')]});
D('baby-sitter',{
  etymology:{origin:'baby-sitter 由 baby 与 sitter 组成；sitter 是 sit 加施事后缀 -er，最初指照看婴儿或孩子的人，连字符复合形式见于20世纪初。',prefix:null,root:{text:'sit',gloss:'照看、守在身边'},suffix:{text:'-er',gloss:'表示从事该活动的人'},history:[],formationLogic:'baby + sitter；指暂时代看孩子的人。',mnemonic:null,note:'baby-sitter 与 babysitter 两种拼法均见；本词条保留带连字符形式。',source:'Etymonline — https://www.etymonline.com/word/baby-sitter'},
  contexts:[c('baby-sitter.s1','家庭 · 临时代看','Because both parents were attending the evening meeting, they asked a trusted neighbour to work as a baby-sitter for two hours.','由于父母都要参加晚间会议，他们请一位可信的邻居临时代看孩子两小时。','Because both parents were attending the evening meeting / they / asked a trusted neighbour / to work as a baby-sitter / for two hours.','ask someone to do；as a baby-sitter 表示担任临时看护；for two hours 表时长。','The limited two-hour arrangement while parents are away marks a temporary child-carer, not a resident nanny.'),c('baby-sitter.s1','家庭 · 照料责任','The baby-sitter wrote down the child’s bedtime routine and the parents’ phone number before they left for the concert.','父母去听音乐会前，临时保姆记下了孩子的就寝习惯和父母的电话号码。','The baby-sitter / wrote down the child’s bedtime routine and the parents’ phone number / before they left for the concert.','write down 表示记下；before 引导时间状语从句。','The sitter is responsible for short-term supervision during the parents’ absence.')],
  mistakes:[m('We hired a baby-sitter to live with our family permanently and raise our child full time.','We hired a nanny to live with our family permanently and raise our child full time.','baby-sitter 通常是短时看护；长期住家并全职养育孩子更适合 nanny。')],
  quiz:[q('baby-sitter',1,1,'A family hires a baby-sitter while the parents?','are away for a short time','are permanently replaced as parents','need someone to repair the roof','baby-sitter 是父母短时外出时照看孩子的人。'),q('baby-sitter',2,1,'Which task fits a baby-sitter’s role?','supervising a child for an evening','providing full-time school education','managing the parents’ bank','临时保姆的典型职责是短时间照护孩子。'),q('baby-sitter',3,1,'Which related verb means to care for a child temporarily?','babysit','babyish','babble','babysit 是对应动词，指临时代看孩子。'),q('baby-sitter',4,1,'A permanent live-in child carer is more commonly called a?','nanny','baby-sitter','balloonist','nanny 更常指长期照看孩子的保姆。')]});
D('babyish',{
  etymology:{origin:'babyish 由 baby 加形容词后缀 -ish 构成，后缀表示「有……特征、近似……」；该词可中性指像婴儿，也常批评不成熟。',prefix:null,root:{text:'baby',gloss:'婴儿'},suffix:{text:'-ish',gloss:'具有……特征的'},history:[],formationLogic:'baby + -ish',mnemonic:null,note:'判断褒贬需看语境；babyish 常带不成熟的负面评价。',source:'Etymonline — https://www.etymonline.com/word/babyish'},
  contexts:[c('babyish.s1','性格 · 不成熟','Although the other applicants disagreed, Owen made a babyish face, folded his arms, and refused to discuss the evidence.','尽管其他申请者持不同意见，欧文还是做了个孩子气的鬼脸，抱起手臂拒绝讨论证据。','Although the other applicants disagreed / Owen / made a babyish face / folded his arms / and refused to discuss the evidence.','Although 引导让步从句；made、folded、refused 并列。','The sulking and refusal to discuss evidence make babyish mean immature and foolish rather than endearingly childlike.'),c('babyish.s1','举止 · 幼稚反应','Calling a colleague names because she received the promotion was a babyish response to disappointment.','因为同事获得晋升就辱骂她，是一种面对失望时幼稚的反应。','Calling a colleague names / because she received the promotion / was a babyish response / to disappointment.','动名词短语作主语；because 引导原因；to disappointment 修饰 response。','The insult after losing out at work is an immature response, the critical sense of babyish.')],
  mistakes:[m('He accepted the decision calmly, congratulated the winner, and described his reaction as babyish.','He sulked, insulted the winner, and behaved in a babyish way.','冷静接受並祝贺胜者不是幼稚行为；babyish 应对应任性、不成熟的举止。')],
  quiz:[q('babyish',1,1,'A babyish reaction to losing might involve?','sulking and refusing to accept the result','congratulating the winner graciously','checking the score carefully','babyish 常形容任性、不成熟的反应。'),q('babyish',2,1,'In the source, the suffix -ish helps form?','an adjective meaning having baby-like qualities','a verb meaning to care for children','a noun meaning a hired caregiver','baby + -ish 构成形容词 babyish。'),q('babyish',3,1,'Which adjective is usually more positive than babyish?','childlike','childish','babyish','childlike 常可褒义地表示天真可爱，而 babyish 往往带批评。'),q('babyish',4,1,'A manager pouting over a minor correction is acting?','babyish','barometric','azure','因小事撅嘴闹情绪体现不成熟。')]});
D('Babylonian',{
  etymology:{origin:'Babylonian 由专名 Babylon 加形容词后缀 -ian 构成，约17世纪用于指古巴比伦城、居民及其帝国；奢靡义来自后世文学中的巴比伦意象。',prefix:null,root:{text:'Babylon',gloss:'古巴比伦'},suffix:{text:'-ian',gloss:'表示所属或相关的形容词后缀'},history:[],formationLogic:'Babylon + -ian；专名派生形容词。',mnemonic:null,note:'历史描述通常是中性；文学转义「奢靡、放纵」有特定语境。',source:'Etymonline — https://www.etymonline.com/word/Babylonian'},
  contexts:[c('Babylonian.s1','历史 · 古文明','The museum displayed a Babylonian tablet whose carefully pressed marks recorded grain deliveries to a temple storehouse.','博物馆展出了一块巴比伦泥板，上面压印的文字记录了运往神庙仓库的谷物。','The museum / displayed a Babylonian tablet / whose carefully pressed marks / recorded grain deliveries / to a temple storehouse.','whose 引导定语从句；recorded 是从句谓语。','Babylonian modifies a historical artifact associated with ancient Babylon, not a modern religious judgment.'),c('Babylonian.s2','文学 · 奢靡描写','The novelist describes the resort’s Babylonian excess through gold-plated rooms, endless feasts, and guests who flaunt their wealth.','小说家通过镀金房间、无休止的宴席和炫富的宾客，把度假村描写成奢靡放纵之所。','The novelist / describes the resort’s Babylonian excess / through gold-plated rooms / endless feasts / and guests who flaunt their wealth.','through 引出描写手段；who 引导定语从句修饰 guests。','The conspicuous luxury signals the literary figurative sense; it is not a neutral label for Babylonian history.')],
  mistakes:[m('The archaeologist called the clay tablet Babylonian because it had been made in ancient Babylon, and meant no criticism.','The archaeologist called the clay tablet Babylonian because it had been made in ancient Babylon.','历史义 Babylonian 是来源或所属的中性形容词；不应把它误解为「奢靡放纵」的贬义转义。')],
  quiz:[q('Babylonian',1,1,'A Babylonian tablet is associated with?','the ancient city and empire of Babylon','a modern language school in Paris','a musical instrument from Greece','第一义指古巴比伦的所属或相关事物。'),q('Babylonian',2,2,'A “Babylonian excess” in a novel most likely suggests?','extravagant luxury or moral indulgence','a quiet archaeological lecture','a plain farming tool','第二义是文学语境中的奢靡、放纵。'),q('Babylonian',3,1,'In “Babylonian records,” Babylonian is?','an adjective describing historical origin','a verb meaning to excavate','a plural noun for tablets','Babylonian 在这里修饰 records，作形容词。'),q('Babylonian',4,1,'The suffix -ian in Babylonian chiefly marks?','a relation to a place or people','a past-tense verb','a small physical size','-ian 常构成表示所属或相关的形容词。')]});
D('babysit',{
  etymology:{origin:'babysit 由 baby 与 sit 复合而来，20世纪初出现，字面是「坐在婴儿旁照看」；过去式和过去分词为 babysat。',prefix:null,root:{text:'baby + sit',gloss:'婴儿；坐守、照看'},suffix:null,history:[],formationLogic:'baby + sit；复合动词表示临时照看孩子。',mnemonic:null,note:'通常为不及物用法，常说 babysit for a family；也可及物接 child。',source:'Etymonline — https://www.etymonline.com/word/babysit'},
  contexts:[c('babysit.s1','家庭 · 临时照料','I agreed to babysit for the Ng family on Friday, so they could attend the school concert together.','我答应周五替吴家照看孩子，这样他们就能一起参加学校音乐会。','I / agreed to babysit for the Ng family on Friday / so they could attend the school concert together.','agree to 后接动词原形；babysit for someone 表示替某家照看孩子；so 引导结果。','babysit describes temporary child care while the usual caregivers are away.'),c('babysit.s1','家庭 · 安全照护','While babysitting, Mara checked the written allergy instructions before serving the child a snack.','临时代看孩子时，玛拉在给孩子零食前查看了书面过敏说明。','While babysitting / Mara / checked the written allergy instructions / before serving the child a snack.','While + 现在分词作时间状语；before serving 表示先后。','The allergy instructions and snack supervision show responsible short-term care, not merely being in the same room.')],
  mistakes:[m('I babysat the children every weekday for a year as their live-in caregiver, although the job was only occasional evening care.','I worked as a nanny for the children every weekday for a year.','babysit 通常指临时照看；持续一年、每个工作日担任住家照料者更应称 nanny。')],
  quiz:[q('babysit',1,1,'If you babysit for a neighbour, you?','look after the neighbour’s child temporarily','teach the neighbour to drive','repair the neighbour’s roof','babysit 指父母外出时临时代为照看孩子。'),q('babysit',2,1,'What is the past tense of babysit?','babysat','babysitted','babysiting','babysit 的不规则过去式为 babysat。'),q('babysit',3,1,'Which phrase is natural?','babysit for the family','babysit at the family to','babysit from the family of','常用 babysit for someone，表示替某人看孩子。'),q('babysit',4,1,'A person watching a child for two hours while the parents dine out is likely to?','babysit','bask','barricade','短时替父母照料孩子正是 babysit 的意思。')]});
D('backbreaking',{
  etymology:{origin:'backbreaking 由 back「背部」与 breaking「使折断、压垮」组成，约19世纪中期开始形容艰苦到仿佛折断腰背的体力劳动。',prefix:null,root:{text:'back',gloss:'背部'},suffix:null,history:[],formationLogic:'back + breaking；以腰背被压垮的夸张形象描述重体力劳动。',mnemonic:null,note:'常修饰 physical work、labour、task；不是一般智力难题的同义词。',source:'Etymonline — https://www.etymonline.com/word/backbreaking'},
  contexts:[c('backbreaking.s1','劳动 · 体力活','For three weeks the crew did backbreaking work, lifting wet stone blocks by hand before the hillside path could be reopened.','在山坡小路重新开放前，施工队连续三周徒手搬运湿石块，干着极其繁重的体力活。','For three weeks / the crew / did backbreaking work / lifting wet stone blocks by hand / before the hillside path could be reopened.','do work；lifting 分词说明工作内容；before 引导时间状语。','Manual lifting of heavy wet blocks makes this literally exhausting physical labour.'),c('backbreaking.s2','劳动 · 长时疲惫','After a month of backbreaking shifts in the harvest fields, the seasonal workers were given two days to rest.','在收割田里连续干了一个月令人累垮的班次后，季节工获准休息两天。','After a month of backbreaking shifts / in the harvest fields / the seasonal workers / were given two days to rest.','After + 名词短语作时间状语；被动 were given；to rest 表目的。','The month-long physical shifts emphasize the exhausting effect over time, matching the second source sense.')],
  mistakes:[m('She called the quiet desk review backbreaking physical labour, although she never moved or lifted anything.','She called the long day of lifting cement bags backbreaking physical labour.','backbreaking 指繁重得使人腰背疲惫的体力工作；安静审阅文件不属于该类劳动。')],
  quiz:[q('backbreaking',1,1,'Backbreaking work usually demands?','very hard physical effort','no physical effort at all','only a brief conversation','backbreaking 主要形容艰苦的重体力劳动。'),q('backbreaking',2,2,'After backbreaking shifts, workers are likely to feel?','extremely physically tired','fresh without any exertion','confused about a word’s spelling','长时间劳作让人身体疲惫，符合第二义。'),q('backbreaking',3,1,'Which task best fits the adjective?','carrying heavy stones up a steep slope','reading a short email at a desk','choosing a song for a party','搬运重物上坡是繁重体力活。'),q('backbreaking',4,1,'The adjective is formed around the image of?','work so hard it seems to break one’s back','work done only in a bakery','a person breaking a wooden chair','backbreaking 以腰背被压垮的形象表达极其艰苦。')]});
D('backdrop',{
  etymology:{origin:'backdrop 原为剧院舞台术语，back「后面」加 drop「垂挂的布景」，指演员后方悬挂的大幅绘景；20世纪初扩展出抽象的事件背景义。',prefix:null,root:{text:'back',gloss:'后方'},suffix:null,history:[],formationLogic:'back + drop（悬挂的布景）；从舞台背景转指事情发生的大环境。',mnemonic:null,note:'抽象义常见 against a backdrop of；与个人经历意义较宽的 background 有别。',source:'Etymonline — https://www.etymonline.com/word/backdrop'},
  contexts:[c('backdrop.s1','剧院 · 舞台布景','The stage crew lowered a painted mountain backdrop behind the actors before the second scene began.','第二幕开始前，舞台工作人员把一幅绘制山景的背景幕降到演员身后。','The stage crew / lowered a painted mountain backdrop / behind the actors / before the second scene began.','lower + 宾语；painted 修饰 backdrop；before 引导时间状语。','The physical cloth lowered behind actors is the original theatre sense of backdrop.'),c('backdrop.s2','社会 · 事件背景','Against a backdrop of rising food prices, the charity expanded its school-lunch programme in three rural districts.','在食品价格上涨的大背景下，这家慈善机构把学校午餐计划扩展到三个农村地区。','Against a backdrop of rising food prices / the charity / expanded its school-lunch programme / in three rural districts.','against a backdrop of 引出环境条件；rising 分词修饰 prices。','The price trend is the general situation against which the charity’s decision takes place, the figurative sense.')],
  mistakes:[m('The painted cloth hanging behind the actors was called a personal backdrop because it described the lead actor’s childhood.','The painted cloth hanging behind the actors was called a stage backdrop.','舞台上演员身后的绘布是字面 backdrop；个人童年经历更接近 background。')],
  quiz:[q('backdrop',1,1,'A theatre backdrop is?','a large scene cloth behind the actors','a light carried by each actor','the stage floor in front of the curtain','backdrop 的原义是舞台上演员后方悬挂的布景。'),q('backdrop',2,2,'“Against a backdrop of inflation” means?','with inflation as the surrounding situation','with a painted curtain behind the speaker','without any economic conditions','抽象义 backdrop 指事件发生时的整体环境。'),q('backdrop',3,1,'Which phrase is common for the figurative sense?','against a backdrop of change','backdrop into the change','beneath a backdrop on change','against a backdrop of 表示在某种大背景下。'),q('backdrop',4,2,'A person’s childhood history is more commonly their?','background','backdrop','backhand','个人经历通常称 background；backdrop 多指事件环境。')]});
D('backhand',{
  etymology:{origin:'backhand 由 back 与 hand 组成，19世纪用于网球等运动中以手背一侧朝向击球的动作；随后既作球拍击法名词，也作相应动词。',prefix:null,root:{text:'back',gloss:'手背一侧'},suffix:null,history:[],formationLogic:'back + hand；描述以手背一侧挥拍的击球方式。',mnemonic:null,note:'backhanded compliment 是「表面夸奖、实际挖苦」的固定比喻搭配，不等于体育击球。',source:'Etymonline — https://www.etymonline.com/word/backhand'},
  contexts:[c('backhand.s1','运动 · 网球击球','On the final point, Imani drove a backhand down the line, sending the ball past her opponent before she could recover.','最后一分时，伊曼妮沿边线打出一记反手球，球从对手身旁掠过，对手来不及回位。','On the final point / Imani / drove a backhand down the line / sending the ball past her opponent / before she could recover.','drive a backhand 指有力地打反手球；sending 分词表示结果。','The racket sport and shot direction identify backhand as the stroke played with the opposite side of the hand facing the ball.'),c('backhand.s2','运动 · 击球动作','Because the ball bounced behind him, the player backhanded it across the court instead of turning for a forehand.','由于球弹到了他身后，球员用反手将球击过球场，而没有转身打正手。','Because the ball bounced behind him / the player / backhanded it across the court / instead of turning for a forehand.','Because 引导原因从句；backhanded 是动词过去式；instead of 后接动名词。','Here backhanded is the verb “hit with a backhand stroke,” contrasted directly with a forehand.')],
  mistakes:[m('She returned the serve with a backhand, striking the ball with the palm-facing forehand motion.','She returned the serve with a forehand, striking the ball with the palm-facing motion.','backhand 与 forehand 是不同击球方式；手掌一侧朝向球应称 forehand。')],
  quiz:[q('backhand',1,1,'In tennis, a backhand is?','a racket stroke hit from the opposite side of the palm','a serve that never crosses the net','a ball caught by hand','backhand 是以手背一侧朝向球的反手击球。'),q('backhand',2,2,'To backhand the ball means to?','hit it with a backhand stroke','catch it and carry it off court','serve it under the net','backhand 作动词意为用反手击球。'),q('backhand',3,1,'If a player uses the palm-facing stroke, the shot is a?','forehand','backhand','barrage','手掌一侧朝球的击球是 forehand。'),q('backhand',4,1,'A “backhanded compliment” is usually?','praise that contains an insult','a clean tennis winner','a direct apology','固定搭配 backhanded compliment 指暗含挖苦的夸奖。')]});
D('backlash',{
  etymology:{origin:'backlash 由 back 与 lash「猛击、抽打」组成，19世纪初用于指机械部件间的回弹或松隙，之后比喻对某项改变的强烈反对。',prefix:null,root:{text:'back',gloss:'向后'},suffix:null,history:[],formationLogic:'back + lash（猛击）；由向后的机械冲击发展为强烈反弹。',mnemonic:null,note:'社会义常与 against 搭配；机械义可指齿轮间隙或回冲。',source:'Etymonline — https://www.etymonline.com/word/backlash'},
  contexts:[c('backlash.s1','公共政策 · 反对','The council faced a public backlash after it announced the closure of three libraries without consulting neighbourhood groups.','市政委员会未经社区团体协商就宣布关闭三座图书馆，随后遭到公众强烈反对。','The council / faced a public backlash / after it announced the closure of three libraries / without consulting neighbourhood groups.','face backlash 表示面临强烈反对；after 引导时间从句；without 后接动名词。','The hostile public response is caused by a decision seen as going too far, the social sense of backlash.'),c('backlash.s2','机械 · 回冲','The engineer fitted a tighter gear assembly to reduce backlash, so the steering wheel would respond without a loose delay.','工程师安装了更紧密的齿轮组件以减少齿隙，这样方向盘就不会出现松动迟滞。','The engineer / fitted a tighter gear assembly / to reduce backlash / so the steering wheel would respond / without a loose delay.','to reduce 表目的；so 引导结果从句；would respond 表预期效果。','The loose delay between connected gears identifies the mechanical play sense of backlash.')],
  mistakes:[m('The new rule was welcomed by every affected group, so officials described the reaction as a fierce backlash against it.','The new rule was welcomed by every affected group, so officials described the reaction as strong support for it.','backlash 是强烈反对或反弹；全体欢迎的反应应称 support。')],
  quiz:[q('backlash',1,1,'A public backlash is?','a strong negative reaction to a decision','a quiet, unanimous vote of approval','a formal invitation to a meeting','backlash 的社会义是因变化过度而起的强烈反对。'),q('backlash',2,2,'In a gear system, backlash can refer to?','play or looseness between connected parts','the colour of the lubricant','a driver’s written complaint','机械义包括部件之间的空隙或回冲。'),q('backlash',3,1,'Which phrase fits the public-reaction sense?','a backlash against the proposal','a backlash in the weather forecast','a backlash of three metres long','社会义通常用 backlash against 表示对某事的反对。'),q('backlash',4,1,'What may trigger a backlash?','a change people think has gone too far','a decision accepted without objection','a gear with no moving parts','当人们认为某项改变走得太远时，可能出现反弹。')]});
D('backlight',{
  etymology:{origin:'backlight 是 back「后方」加 light「照明」组成的复合动词，摄影与舞台语境中指从对象后方向其照光，使轮廓显现。',prefix:null,root:{text:'back',gloss:'后方'},suffix:null,history:[],formationLogic:'back + light；从物体后侧打光。',mnemonic:null,note:'本词条主要收动词义；名词 backlight 可指背光或逆光。',source:'Etymonline — https://www.etymonline.com/word/backlight'},
  contexts:[c('backlight.s1','摄影 · 轮廓光','The cinematographer backlit the glass bottles so their edges glowed while the labels remained readable against the dark shelf.','摄影师从后方给玻璃瓶打光，使瓶身边缘发亮，同时标签仍能在深色架子前辨认。','The cinematographer / backlit the glass bottles / so their edges glowed / while the labels remained readable / against the dark shelf.','backlit 是 backlight 的过去式；so 引导结果；while 表示对比。','The source of light is placed behind the bottles, producing glowing edges, which precisely illustrates backlight as a verb.'),c('backlight.s1','舞台 · 背后照明','For the final tableau, the crew backlit the dancers with a pale blue wash to separate their silhouettes from the scenery.','最后的定格画面中，工作人员用淡蓝色灯光从后方照亮舞者，使其轮廓从布景中显现出来。','For the final tableau / the crew / backlit the dancers / with a pale blue wash / to separate their silhouettes from the scenery.','with 引出灯光方式；to separate 表目的。','The rear light makes the dancers’ silhouettes distinct from the background, the intended lighting technique.')],
  mistakes:[m('The photographer backlit the portrait by placing the only lamp directly in front of the subject and behind the camera.','The photographer front-lit the portrait by placing the only lamp directly in front of the subject.','backlight 必须从被摄对象后方照射；灯在正前方是 front-light。')],
  quiz:[q('backlight',1,1,'To backlight an object, a photographer places a light?','behind the object','under the floor only','inside the camera lens','backlight 作动词表示从物体后方向其照明。'),q('backlight',2,1,'What effect can backlighting create?','a glowing edge or clear silhouette','a shadow cast from the camera operator only','a change in the object’s material','后方照光常使物体轮廓显现或边缘发亮。'),q('backlight',3,1,'A light placed in front of a subject is more accurately described as?','front light','backlight','moonlight','正面照明与 backlight 的方向相反。'),q('backlight',4,1,'Which is the correct past tense?','backlit','backlighted only','backlited','该词常见过去式是 backlit。')]});
D('backpack',{
  etymology:{origin:'backpack 是 back「背部」与 pack「包裹、背包」组成的现代复合词，指背在身上的包；backpack 作名词和动词的用法均与此复合构词相关。',prefix:null,root:{text:'back + pack',gloss:'背部 + 包裹'},suffix:null,history:[],formationLogic:'back + pack，指背在背上的行李包。',mnemonic:null,note:'英式英语也常说 rucksack；backpacker 指背包旅行者。',source:'Etymonline — https://www.etymonline.com/word/backpack'},
  contexts:[c('backpack.s1','旅行 · 装行李','Before the overnight hike, Jun packed a rain jacket, water filter, and paper map into his backpack and tightened the shoulder straps.','夜间徒步前，俊把雨衣、滤水器和纸地图装进背包，并收紧肩带。','Before the overnight hike / Jun / packed a rain jacket, water filter, and paper map / into his backpack / and tightened the shoulder straps.','pack items into a bag；before 引导时间状语；并列谓语 packed、tightened。','The worn over-the-shoulder pack holding hiking supplies is the concrete noun sense of backpack.'),c('backpack.s1','校园 · 随身携带','The student left her backpack beside the lecture-hall door, then returned for it when she realized her laptop was still inside.','学生把双肩包放在讲堂门边，发现笔记本电脑还在里面后又回去取。','The student / left her backpack beside the lecture-hall door / then returned for it / when she realized her laptop was still inside.','leave + 宾语 + 地点；when 引导时间从句；it 指 backpack。','The backpack is a bag carried on the back and used here to transport school belongings.')],
  mistakes:[m('The hiker carried a backpack by dragging it behind the bicycle on a trailer, with no straps or contact with the back.','The hiker carried a backpack on her back using its shoulder straps.','backpack 的词义特指背在身上的包；拖挂行李不符合此物品的使用方式。')],
  quiz:[q('backpack',1,1,'A backpack is designed to be carried?','on the back','as a ring around the ankle','by attaching it to a rifle','backpack 是背在背上的包。'),q('backpack',2,1,'Which items might a hiker put into a backpack?','water and a rain jacket','a stage backdrop and curtain rail','a set of legal verdicts only','徒步者常把水和雨衣装入背包。'),q('backpack',3,1,'Which word is also used in British English for a backpack?','rucksack','balsam','ballad','rucksack 是英式常见对应说法。'),q('backpack',4,1,'A backpack’s shoulder straps are used to?','secure the bag on the wearer’s back','tie two wheels to an axle','decorate a dancing room','肩带把背包固定在背部。')]});
D('bacterial',{
  etymology:{origin:'bacterial 由 bacterium 的词干加形容词后缀 -al 构成；bacterium 源自新拉丁语，借希腊语 bakterion「小杖」，因早期观察到的细菌常呈杆状。',prefix:null,root:{text:'bacterium',gloss:'细菌'},suffix:{text:'-al',gloss:'构成形容词'},history:[],formationLogic:'bacteri- + -al；形容与细菌有关或由细菌造成。',mnemonic:null,note:'不要把 bacterial infection 与 viral infection 混为一谈。',source:'Etymonline — https://www.etymonline.com/word/bacterial'},
  contexts:[c('bacterial.s1','生物 · 微生物','The laboratory confirmed that the sample contained bacterial growth, so the technicians disinfected the bench before beginning another test.','实验室确认样本中有细菌生长，因此技术员在开始另一项检测前先给工作台消毒。','The laboratory / confirmed that the sample contained bacterial growth / so the technicians / disinfected the bench / before beginning another test.','that 引导宾语从句；so 表结果；before + 动名词。','bacterial modifies growth to identify microorganisms of the bacterial kind.'),c('bacterial.s2','医疗 · 感染病因','Because the culture identified a bacterial infection rather than a virus, the clinician selected a treatment based on the test result.','由于培养结果确定这是细菌感染而非病毒感染，临床医生依据检测结果选择了治疗方案。','Because the culture identified a bacterial infection rather than a virus / the clinician / selected a treatment / based on the test result.','Because 引导原因；rather than 连接对照项；based on 作后置修饰。','The contrast with a virus specifies the source sense: an illness caused by bacteria.')],
  mistakes:[m('The lab called the illness bacterial, then explained that tests had ruled out bacteria and confirmed only a virus.','The lab called the illness viral, then explained that tests had ruled out bacteria and confirmed a virus.','bacterial 表示与细菌有关或由细菌导致；已确认病毒时应写 viral。')],
  quiz:[q('bacterial',1,1,'Bacterial growth in a culture consists of?','bacteria multiplying in the sample','only a cloud of water vapour','a group of animal footprints','bacterial 的一般义是与细菌有关。'),q('bacterial',2,2,'A bacterial infection is caused by?','bacteria rather than a virus','a broken axle','a shortage of vitamins only','感染义强调致病原因是细菌。'),q('bacterial',3,1,'Which is the adjective related to bacterium?','bacterial','bacteriallyness','bacterianer','bacterial 是 bacterium 的相关形容词。'),q('bacterial',4,2,'If a test identifies a virus, the illness is described as?','viral','bacterial','balmy','病毒导致的感染称 viral，而非 bacterial。')]});
D('bacterium',{
  etymology:{origin:'bacterium 是19世纪引入的现代拉丁科学名词，来自希腊语 baktērion「小杖」；该词指杆状微生物，bacteria 是其复数形式。',prefix:null,root:{text:'Greek baktērion',gloss:'小杖'},suffix:null,history:[],formationLogic:null,mnemonic:null,note:'标准单数是 bacterium，复数是 bacteria；biological use distinguishes a microscopic organism from a type or species. ',source:'Etymonline — https://www.etymonline.com/word/bacterium'},
  contexts:[c('bacterium.s1','实验 · 单个微生物','Under the microscope, the researcher isolated one bacterium from the water sample and recorded its shape before culturing it.','研究人员在显微镜下从水样中分离出一只细菌，培养前记录了它的形状。','Under the microscope / the researcher / isolated one bacterium from the water sample / and recorded its shape / before culturing it.','one 后用单数 bacterium；并列谓语 isolated、recorded；before + 动名词。','The numeral one and reference to a single cell organism establish the singular general sense.'),c('bacterium.s2','医疗 · 病原体','The physician identified the bacterium responsible for the wound infection and chose a medicine that targeted that organism.','医生找出了导致伤口感染的致病菌，并选择了一种针对该微生物的药物。','The physician / identified the bacterium responsible for the wound infection / and chose a medicine / that targeted that organism.','responsible for 后接名词；that 引导修饰 medicine 的定语从句。','This sense highlights a disease-causing bacterium, explicitly identified as the source of infection.')],
  mistakes:[m('The laboratory isolated one bacteria from the sample and recorded its shape.','The laboratory isolated one bacterium from the sample and recorded its shape.','one 后用单数 bacterium；bacteria 是复数形式。')],
  quiz:[q('bacterium',1,1,'What is the standard singular form?','bacterium','bacteria','bacteriums only','bacterium 是单数形式。'),q('bacterium',2,1,'What is its usual plural?','bacteria','bacteriumes','bacterias','bacteria 是 bacterium 的不规则拉丁复数。'),q('bacterium',3,2,'A bacterium isolated from an infected wound may be?','the organism causing the infection','a piece of medical gauze','a harmless spelling mark','bacterium 的第二义指致病菌。'),q('bacterium',4,1,'Why does the word’s Greek source relate to a “small staff”?','early described bacteria could be rod-shaped','the organisms carried walking sticks','the word originally meant a medical doctor','词源中的“小杖”与早期描述的杆状细菌有关。')]});
D('badger',{
  etymology:{origin:'badger 作动物名约在16世纪出现，可能由 badge 与后缀 -ard 构成，或与动物额头白色斑纹有关；这一解释不确定。动词「纠缠」来自猎狗反复攻击獾的旧式斗獾活动。',prefix:null,root:null,suffix:null,history:[],formationLogic:null,mnemonic:null,note:'动物名词源有推测成分；动词义历史上与 badger-baiting 相联系。',source:'Etymonline — https://www.etymonline.com/word/badger'},
  contexts:[c('badger.s1','野生动物 · 夜行','The wildlife camera recorded a badger digging for insects beside the hedgerow after the farm lights had gone out.','农场的灯熄灭后，野生动物摄像机拍到一只獾在树篱旁挖掘寻找昆虫。','The wildlife camera / recorded a badger digging for insects / beside the hedgerow / after the farm lights had gone out.','record + 宾语 + 现在分词；after 引导时间从句。','Night activity, digging, and hedgerows point to the burrowing mammal sense.'),c('badger.s2','沟通 · 反复催问','The reporter badgered the spokesperson for a direct answer, repeating the same question after each vague reply.','记者反复追问发言人要一个直接答复，每次得到含糊回应后都重复同一个问题。','The reporter / badgered the spokesperson for a direct answer / repeating the same question / after each vague reply.','badger someone for an answer 表示纠缠索要答复；repeating 分词说明方式。','The repeated pressure after evasive replies makes badger mean pester persistently.')],
  mistakes:[m('The reporter badgered the spokesperson once, accepted the answer, and never raised the subject again.','The reporter asked the spokesperson once, accepted the answer, and never raised the subject again.','badger 暗含持续纠缠或反复烦扰；只问一次就接受回答并不构成 badger。')],
  quiz:[q('badger',1,1,'A badger in a nature report is?','a digging mammal with a striped face','a flying insect with transparent wings','a sea fish with a shell','badger 的动物义是獾。'),q('badger',2,2,'To badger someone with questions is to?','pester them repeatedly','ask one polite question and stop','leave them a written compliment','badger 作动词表示一再烦扰、纠缠。'),q('badger',3,1,'Which context most likely contains the animal sense?','a camera recording a burrowing mammal at night','a journalist repeating the same request','a child asking once for permission','夜间洞穴、觅食的动物语境符合獾义。'),q('badger',4,2,'Which action is a clear example of badgering?','repeatedly pressuring a colleague for an answer','thanking a colleague once for help','reading a colleague’s report silently','反复施压索要答复体现 badger 的动词义。')]});
D('baedeker',{
  etymology:{origin:'baedeker 作为普通名词指旅行指南，1857年前后由德国出版商 Karl Baedeker 的姓氏转化而来；其旅行指南系列使姓氏成为指南的通称。',prefix:null,root:{text:'Baedeker',gloss:'德国出版商姓氏'},suffix:null,history:[],formationLogic:'专有姓氏转为普通名词，指详尽的旅行指南。',mnemonic:null,note:'泛指旅行指南时可小写 baedeker；指出版商本人时大写 Baedeker。',source:'Etymonline — https://www.etymonline.com/word/Baedeker'},
  contexts:[c('baedeker.s1','旅行 · 纸本指南','Before taking the train inland, the couple checked their baedeker for the museum’s opening hours and the walking route from the station.','乘火车去内陆前，这对夫妇查阅旅行指南，确认博物馆开放时间和从车站步行的路线。','Before taking the train inland / the couple / checked their baedeker / for the museum’s opening hours / and the walking route from the station.','check something for details；before + 动名词作时间状语；并列宾语。','Opening hours and a mapped tourist route are practical contents of a travel guidebook.'),c('baedeker.s1','旅行 · 城市观光','The old baedeker included a short description of each monument, allowing visitors to plan a day without an internet connection.','这本旧旅行指南简要介绍了每座纪念碑，让游客不用联网也能安排一天的行程。','The old baedeker / included a short description of each monument / allowing visitors / to plan a day / without an internet connection.','allow someone to do；allowing 分词说明结果。','A printed guide describing attractions and helping plan visits fits the guidebook sense.')],
  mistakes:[m('The traveler opened a baedeker to check the bus route, but the word meant a musical instrument with six strings.','The traveler opened a baedeker to check the bus route in the guidebook.','baedeker 是旅行指南，不是弦乐器；上下文的查路线也明确支持指南义。')],
  quiz:[q('baedeker',1,1,'A traveler consults a baedeker to find?','information about places and routes','the temperature inside a laboratory flask','instructions for repairing a rifle','baedeker 指旅行指南。'),q('baedeker',2,1,'Why can baedeker be written with a lowercase initial?','The publisher’s surname became a common noun for a guidebook.','It is always an adjective with no proper-name origin.','It names a type of river fish.','普通名词义源于出版商姓氏的通用化。'),q('baedeker',3,1,'Which would most likely appear in a baedeker?','museum hours and a walking itinerary','a detailed recipe for soup','a court verdict about a contract','旅行指南会列出景点信息和游览路线。'),q('baedeker',4,1,'The word is associated with which person?','German publisher Karl Baedeker','a French tennis champion','an ancient Roman emperor','该词源自德国出版商 Karl Baedeker 的姓氏。')]});
D('bagel',{
  etymology:{origin:'bagel 于20世纪初由意第绪语 beygl「环形面包」进入英语；该意第绪词与中古高地德语 boug「环、手镯」有关，最终源头含「弯曲」之意。',prefix:null,root:{text:'Yiddish beygl',gloss:'环形面包；与“环”有关'},suffix:null,history:[],formationLogic:null,mnemonic:null,note:'bagel 先煮后烤，口感通常紧实有嚼劲。',source:'Etymonline — https://www.etymonline.com/word/bagel'},
  contexts:[c('bagel.s1','早餐 · 烘焙食品','For breakfast, Nia sliced a warm bagel, spread it with cream cheese, and packed the other half for the train.','早餐时，妮娅切开一个热贝果，抹上奶油奶酪，并把另一半装起来带上火车。','For breakfast / Nia / sliced a warm bagel / spread it with cream cheese / and packed the other half for the train.','并列动词 sliced、spread、packed；spread A with B 表示把 B 涂在 A 上。','The ring-shaped chewy bread served with cream cheese identifies the food sense.'),c('bagel.s1','食品 · 烘烤工艺','Unlike an ordinary bread roll, a bagel is boiled briefly before it is baked, giving the crust its characteristic chew.','与普通小面包不同，贝果在烘烤前会短暂水煮，因此外皮有独特的嚼劲。','Unlike an ordinary bread roll / a bagel / is boiled briefly / before it is baked / giving the crust its characteristic chew.','被动语态 is boiled / is baked；giving 分词说明结果。','Brief boiling followed by baking is a defining preparation method of bagels.')],
  mistakes:[m('The baker called the ring-shaped bread a bagel, although it was a soft roll baked without first being boiled.','The baker called the chewy ring-shaped bread a bagel after briefly boiling it before baking.','贝果通常先煮后烤并有嚼劲；未煮过的普通软面包卷不能仅因形状就符合本词条定义。')],
  quiz:[q('bagel',1,1,'A bagel is a?','chewy ring-shaped bread roll','flat sheet of pasta','sweet citrus fruit','bagel 是环形、有嚼劲的面包。'),q('bagel',2,1,'What is distinctive about the traditional preparation?','It is boiled before it is baked.','It is frozen after being fried in oil.','It is never exposed to heat.','bagel 的常见制作方式是在烘烤前先煮。'),q('bagel',3,1,'Cream cheese is commonly spread on a?','bagel','backdrop','bacterium','奶油奶酪常搭配贝果食用。'),q('bagel',4,1,'Which language supplied the word to English?','Yiddish','Japanese','Arabic','英语 bagel 借自意第绪语 beygl。')]});
D('baldness',{
  etymology:{origin:'baldness 由形容词 bald 加名词后缀 -ness 构成，表示 bald 的状态或性质；bald 的更早来源不确定，故不进一步猜测其词根。',prefix:null,root:{text:'bald',gloss:'秃的；直白的'},suffix:{text:'-ness',gloss:'构成性质或状态名词'},history:[],formationLogic:'bald + -ness；由形容词构成状态名词。',mnemonic:null,note:'除脱发或无植被外，也可指说法缺乏修饰、过于直白。',source:'Etymonline — https://www.etymonline.com/word/baldness'},
  contexts:[c('baldness.s1','健康 · 脱发','The dermatologist explained that the patient’s gradual baldness had several possible causes and ordered tests before recommending treatment.','皮肤科医生解释说，患者逐渐脱发可能有多种原因，并在建议治疗前安排了检查。','The dermatologist / explained that the patient’s gradual baldness had several possible causes / and ordered tests / before recommending treatment.','that 引导宾语从句；and 连接并列谓语；before + 动名词。','Gradual loss of scalp hair identifies the physical sense of baldness.'),c('baldness.s2','写作 · 直白表达','The editor objected to the baldness of the report’s conclusion, which stated the accusation without acknowledging the uncertainty in the evidence.','编辑不满报告结论过于直白，因为它直接写出指控，却没有承认证据存在不确定性。','The editor / objected to the baldness of the report’s conclusion / which stated the accusation / without acknowledging the uncertainty in the evidence.','object to 后接名词；which 引导定语从句；without 后接动名词。','Here baldness describes blunt, unsoftened wording rather than a lack of hair.')],
  mistakes:[m('The report used carefully qualified language and acknowledged every uncertainty, yet the editor praised its baldness for being perfectly cautious.','The report stated the accusation without qualification, and the editor criticized the baldness of its wording.','第二义的 baldness 指直白、缺乏修饰；谨慎限定的语言与这种「赤裸直白」相反。')],
  quiz:[q('baldness',1,1,'Medical discussion of baldness concerns?','loss of hair','a lack of rain for one day','a musical voice range','baldness 的常见义是头发缺失或脱落。'),q('baldness',2,2,'The baldness of a statement may mean it is?','blunt and unsoftened','decorated with excessive detail','spoken in a whisper','比喻义指说法直接、不加修饰。'),q('baldness',3,1,'A dermatologist is most likely to discuss baldness as?','a hair-loss condition','a type of theatre curtain','an instrument’s loose gears','皮肤科医生会讨论脱发状况。'),q('baldness',4,2,'A writer removes all hedging and tact; the prose may show?','baldness','balm','barley','毫无缓和、直截了当的表达可称 baldness。')]});
D('bale',{
  etymology:{origin:'bale「大包、捆」约14世纪经古法语 bale 进入英语，法语词可能来自法兰克语或其他日耳曼语，与表示「球、圆团」的词族有关；动词义从名词发展。',prefix:null,root:null,suffix:null,history:[],formationLogic:null,mnemonic:null,note:'此处是包捆义，与发音相近的 bail「保释」不是同一个词。',source:'Etymonline — https://www.etymonline.com/word/bale'},
  contexts:[c('bale.s1','农业 · 捆草','The farmer stacked each bale of hay beneath a waterproof cover before the forecast rain reached the field.','农民在预报中的降雨到达田地前，把每捆干草堆在防水罩布下。','The farmer / stacked each bale of hay / beneath a waterproof cover / before the forecast rain reached the field.','each 后接单数 bale；before 引导时间状语。','A tightly bound unit of hay ready for storage is a bale as a noun.'),c('bale.s2','农业 · 打包','The machine baled the loose straw into compact bundles that could be loaded onto the truck.','机器把散落的稻草压捆成紧实的包，便于装上卡车。','The machine / baled the loose straw into compact bundles / that could be loaded onto the truck.','bale something into bundles；that 引导定语从句修饰 bundles。','The verb means to compress or tie material into bales for handling and transport.')],
  mistakes:[m('The workers baled the straw into a single loose pile that could not be tied, lifted, or transported as a unit.','The workers baled the straw into compact tied bundles that could be lifted and transported.','bale 作动词是将材料压紧、捆扎成包；散堆且无法搬运不符合结果。')],
  quiz:[q('bale',1,1,'A bale of hay is?','a large tightly bound bundle','a single grain of barley','a type of theatre backdrop','bale 名词指稻草等材料扎成的大捆。'),q('bale',2,2,'To bale loose straw means to?','compress and tie it into bundles','scatter it over a road','paint it azure','bale 作动词表示把材料压捆起来。'),q('bale',3,1,'Which phrase most clearly names the object?','a bale of cotton','a bail of cotton','a ballad of cotton','bale 是大包或捆；bail 是保释等不同词。'),q('bale',4,2,'A baler is a machine that helps?','make bales','play a slow song','measure the barometric pressure','baler 是把材料打包成捆的机器。')]});
D('balk',{
  etymology:{origin:'balk 可追溯至古英语 balca「脊、梁、障碍」，来自日耳曼语词根；动词「突然停下、畏缩」约16世纪发展出来，名词和动词也拼作 baulk。',prefix:null,root:null,suffix:null,history:[],formationLogic:null,mnemonic:null,note:'常用 balk at 表示因不情愿或顾虑而拒绝；英式变体拼法 baulk。',source:'Etymonline — https://www.etymonline.com/word/balk'},
  contexts:[c('balk.s1','动物 · 拒绝前进','The horse balked at the narrow bridge, planting its hooves firmly until the handler led it across slowly.','马在狭窄的桥前突然止步，把蹄子牢牢钉在地上，直到驯马师慢慢牵它过去。','The horse / balked at the narrow bridge / planting its hooves firmly / until the handler led it across slowly.','balk at 后接拒绝面对的事物；planting 分词描述动作；until 引导时间从句。','The horse suddenly stops and refuses to proceed because of fear, the literal hesitation sense.'),c('balk.s2','谈判 · 不愿接受','The board balked at the proposed fee increase, asking the supplier to justify each new charge before signing.','董事会不愿接受拟议的费用上涨，要求供应商在签约前解释每项新收费。','The board / balked at the proposed fee increase / asking the supplier / to justify each new charge / before signing.','balk at + 名词；ask someone to do；before signing 省略主语 the board。','The board’s resistance is directed at accepting a proposal, the refusal sense.'),c('balk.s3','计划 · 障碍','A shortage of clean water proved a major balk to the settlement’s expansion into the dry valley.','清洁水源短缺成为定居点向干旱山谷扩张的一大障碍。','A shortage of clean water / proved a major balk / to the settlement’s expansion / into the dry valley.','prove + 名词补语；to 表示构成的障碍所指向的计划。','Balk is a less common noun here for an obstacle that blocks progress.')],
  mistakes:[m('The horse balked at the open, familiar path, trotting forward immediately without hesitation.','The horse balked at the unfamiliar bridge, stopping and refusing to go forward.','balk 表示突然停下或畏缩拒行；毫不犹豫地立即前进与之矛盾。')],
  quiz:[q('balk',1,1,'A horse that balks at a bridge?','stops and refuses to cross','gallops across without pausing','builds a bridge from wood','balk 第一义是突然停步、拒绝继续。'),q('balk',2,2,'A board that balks at a fee increase?','resists accepting the increase','approves it without discussion','measures its colour','balk at an idea means hesitate or refuse to accept it. '),q('balk',3,3,'In “a balk to expansion,” balk means?','an obstacle blocking progress','a formal celebration','a type of travel guide','较少见的名词 balk 可表示障碍或阻挠。'),q('balk',4,2,'Which spelling is also a standard variant of balk?','baulk','bawlk','balker','baulk 是该词的英式拼写变体。')]});
D('ballad',{
  etymology:{origin:'ballad 经古法语 balade、普罗旺斯语 balada 进入英语，原指伴舞的叙事歌；其词根与拉丁语 ballare「跳舞」相关。现代可指叙事歌谣，也可指慢节奏流行情歌。',prefix:null,root:{text:'Latin ballare',gloss:'跳舞'},suffix:null,history:[],formationLogic:null,mnemonic:null,note:'与 ballet「芭蕾舞」拼写和意义不同。',source:'Etymonline — https://www.etymonline.com/word/ballad'},
  contexts:[c('ballad.s1','文学 · 民间叙事歌','The singer learned an old ballad about a sailor’s return, preserving the repeated lines that had helped listeners remember the story.','歌手学会了一首讲述水手归来的古老民谣，并保留了帮助听众记住故事的重复诗句。','The singer / learned an old ballad about a sailor’s return / preserving the repeated lines / that had helped listeners remember the story.','about 引出 ballad 叙述的内容；preserving 分词表示伴随结果；that 引导定语从句。','A song telling a story, especially with repeated stanzas, is the narrative ballad sense.'),c('ballad.s2','流行音乐 · 慢歌','The band ended its set with a quiet ballad, slowing the drums so the audience could hear the singer’s words.','乐队以一首安静的慢情歌结束演出，放慢鼓点让观众听清歌手的歌词。','The band / ended its set with a quiet ballad / slowing the drums / so the audience could hear the singer’s words.','end with；slowing 分词说明手段；so 引导目的或结果。','The slow arrangement and romantic performance make ballad the popular love-song sense.')],
  mistakes:[m('The singer introduced a ballad, then played a fast instrumental piece with no lyrics or story and called it a slow love song.','The singer introduced a ballad, then performed a slow song about love.','慢节奏流行 ballad 通常是歌曲，尤其情歌；无歌词的快速器乐曲不符合此义。')],
  quiz:[q('ballad',1,1,'A traditional ballad often?','tells a story in song or verse','lists laboratory measurements only','describes a dance without any words','ballad 第一义是叙事歌谣或叙事诗。'),q('ballad',2,2,'A pop ballad is usually?','a slow song, often about love','a rapid drum solo with no melody','a spoken weather report','流行音乐中的 ballad 常是慢节奏情歌。'),q('ballad',3,1,'Which topic best fits an old narrative ballad?','a sailor’s journey and return','the exact temperature in a freezer','a list of train fares with no story','叙事歌谣通常通过歌曲讲故事。'),q('ballad',4,1,'Which similar-looking word means a stage dance form?','ballet','ballad','ballroom','ballet 是芭蕾，ballad 是歌谣。')]});
D('balloonist',{
  etymology:{origin:'balloonist 由 balloon 加表示从业者或爱好者的后缀 -ist 构成，指驾驶或乘坐气球的人；balloon 通过法语 ballon 与意大利语 pallone「大球」相关。',prefix:null,root:{text:'balloon',gloss:'气球'},suffix:{text:'-ist',gloss:'从事某活动的人'},history:[],formationLogic:'balloon + -ist',mnemonic:null,note:'指气球驾驶员或乘气球的人，不是出售气球的商贩。',source:'Etymonline — https://www.etymonline.com/word/balloonist'},
  contexts:[c('balloonist.s1','航空 · 热气球飞行','The balloonist checked the burner and wind direction before lifting the basket above the valley at sunrise.','热气球驾驶员在日出时升起吊篮飞越山谷前，检查了燃烧器和风向。','The balloonist / checked the burner and wind direction / before lifting the basket / above the valley / at sunrise.','check 名词并列作宾语；before + 动名词；lift the basket 表示升空。','The pilot checks equipment and controls the ascent, identifying a person who pilots a balloon.'),c('balloonist.s1','运动 · 乘气球','As a young balloonist, Ruth joined a cross-country flight and learned how to steer by changing altitude.','鲁思年轻时就参加了跨地飞行，学习通过改变高度来控制气球方向。','As a young balloonist / Ruth / joined a cross-country flight / and learned / how to steer / by changing altitude.','as 表身份；learn how to do；by + 动名词表示方法。','The person is an active participant in balloon flight, not a seller of balloons.')],
  mistakes:[m('The shop’s balloonist spent the afternoon selling helium toys at the market but had never flown or ridden in one.','The shop’s balloon seller spent the afternoon selling helium toys at the market.','balloonist 指乘坐或驾驶气球的人；售卖气球的人应称 balloon seller。')],
  quiz:[q('balloonist',1,1,'A balloonist is a person who?','pilots or rides in a balloon','designs only the printed pages of a guidebook','sings in a ballroom band','balloonist 指驾驶或乘坐气球的人。'),q('balloonist',2,1,'Which task fits an experienced balloonist?','checking wind before launch','judging a court case','weaving a basket for sale only','气球驾驶员需要在起飞前检查风况。'),q('balloonist',3,1,'The suffix -ist in balloonist most often identifies?','a person involved in an activity','the colour of an object','a place for public bathing','-ist 常表示从事某活动的人。'),q('balloonist',4,1,'A person who sells balloons at a fair is a?','balloon seller','balloonist','bacterium','卖气球的人不一定乘坐或驾驶气球。')]});
D('ballroom',{
  etymology:{origin:'ballroom 由 ball「舞会」与 room「房间」构成，18世纪用于指举行正式舞会的大房间；ball 在此经法语 bal 与拉丁语 ballare「跳舞」有关。',prefix:null,root:{text:'ball + room',gloss:'舞会 + 房间'},suffix:null,history:[],formationLogic:'ball + room；举行舞会的大厅。',mnemonic:null,note:'ballroom dancing 泛指华尔兹、狐步、探戈等社交舞。',source:'Etymonline — https://www.etymonline.com/word/ballroom'},
  contexts:[c('ballroom.s1','建筑 · 舞会空间','The hotel restored its ballroom, repairing the sprung floor and chandeliers before hosting the charity gala.','酒店修复了舞厅，在举办慈善晚宴前修好了弹性地板和枝形吊灯。','The hotel / restored its ballroom / repairing the sprung floor and chandeliers / before hosting the charity gala.','restore + 宾语；repairing 分词说明修复事项；before + 动名词。','A large room prepared for formal dancing and parties is the architectural sense.'),c('ballroom.s2','舞蹈 · 社交活动','They took ballroom after work, learning the basic steps of the waltz and foxtrot with a local instructor.','下班后他们去上交谊舞课，跟当地老师学习华尔兹和狐步的基本舞步。','They / took ballroom after work / learning the basic steps / of the waltz and foxtrot / with a local instructor.','take ballroom 作舞蹈活动的省略用法；learning 分词补充说明课程内容。','The listed dances and lessons identify ballroom as a style or activity of formal social dancing.')],
  mistakes:[m('The ballroom was a cramped storage cupboard with no room for dancing, but the hotel advertised it as a grand dance hall.','The ballroom was a spacious hall designed for dancing.','ballroom 是为正式舞会设计的大房间；狭窄、不能起舞的储物柜不符合其功能。')],
  quiz:[q('ballroom',1,1,'A ballroom is built or arranged for?','formal dancing and parties','storing laboratory chemicals','bathing in a private tub only','ballroom 是举行正式舞会的大厅。'),q('ballroom',2,2,'Ballroom dancing commonly includes?','the waltz and foxtrot','basket weaving and knitting','baseball and badminton','ballroom dancing 包括华尔兹、狐步等交谊舞。'),q('ballroom',3,1,'Which feature would suit a ballroom?','a large open floor for dancing','a narrow locked cupboard','a steep road barrier','宽敞舞池是 ballroom 的典型设施。'),q('ballroom',4,2,'A lesson in ballroom most likely teaches?','formal social dance steps','how to repair an axle','how to diagnose a bacterial infection','ballroom 可指正式社交舞活动。')]});
D('balm',{
  etymology:{origin:'balm 是 balsam 的缩短形式；balsam 经古英语、拉丁语 balsamum 与希腊语 balsamon 传入，最终关联古代芳香树脂名称。',prefix:null,root:null,suffix:null,history:[],formationLogic:null,mnemonic:null,note:'balm 可指舒缓皮肤的香膏，也可比喻令人安心或减轻痛苦的事物；字母 l 不发音。',source:'Etymonline — https://www.etymonline.com/word/balm'},
  contexts:[c('balm.s1','护理 · 外用软膏','After the cold wind cracked his hands, the climber rubbed a little balm over the dry skin before putting on his gloves.','寒风把登山者的手吹裂后，他戴手套前在干燥的皮肤上涂了点软膏。','After the cold wind cracked his hands / the climber / rubbed a little balm over the dry skin / before putting on his gloves.','rub balm over the skin；after 引导时间从句；before + 动名词。','The substance is a soothing ointment applied to skin, the literal medicinal sense.'),c('balm.s2','情绪 · 精神慰藉','Her brother’s quiet message was a balm after the difficult interview, reminding her that one rejection did not define her ability.','艰难的面试后，哥哥发来的温和信息给了她安慰，提醒她一次拒绝并不能定义她的能力。','Her brother’s quiet message / was a balm / after the difficult interview / reminding her / that one rejection did not define her ability.','be a balm 为比喻用法；reminding 分词说明效果；that 引导宾语从句。','The message eases emotional distress, illustrating balm as a source of comfort rather than a topical product.')],
  mistakes:[m('She applied balm to her cut and said it was a mechanical gear with measurable backlash.','She applied balm to her cut and said it was a soothing ointment.','外用 balm 是香脂或镇痛软膏，不是机械部件；切口护理语境确认其字面义。')],
  quiz:[q('balm',1,1,'A balm for dry skin is?','a soothing ointment','a type of warship','a travel guide','balm 的字面义是舒缓皮肤的软膏。'),q('balm',2,2,'A kind word can be a balm because it?','comforts someone who is upset','makes a wound larger','measures the weather','balm 可比喻令人安心、减轻痛苦的事物。'),q('balm',3,1,'Which body of water or machine part is not a balm?','an axle','a skin ointment','a fragrant salve','axle 是车轴，与软膏 balm 不同。'),q('balm',4,1,'Which letter in balm is silent in pronunciation?','l','b','m','balm 中的 l 不发音。')]});
D('balmy',{
  etymology:{origin:'balmy 由 balm 加形容词后缀 -y 构成，早期与香气或舒缓感有关，后来常形容温暖、平静、宜人的天气，也可指芳香。',prefix:null,root:{text:'balm',gloss:'香脂、芳香'},suffix:{text:'-y',gloss:'具有……特征的'},history:[],formationLogic:'balm + -y；由香脂的宜人感觉发展为天气舒适。',mnemonic:null,note:'英式口语 balmy 另可俚语表示「疯疯癫癫」，此词条不以该义为核心。',source:'Etymonline — https://www.etymonline.com/word/balmy'},
  contexts:[c('balmy.s1','天气 · 暖和宜人','The hikers reached the coast on a balmy spring evening, when the air was warm and the sea breeze had nearly stopped.','徒步者在一个温暖宜人的春夜抵达海岸，那时空气暖和，海风几乎停了。','The hikers / reached the coast / on a balmy spring evening / when the air was warm / and the sea breeze had nearly stopped.','on a balmy evening 表时间；when 引导定语从句；and 连接两个状态。','Warm, calm air with little wind is the pleasant-weather sense of balmy.'),c('balmy.s2','气味 · 芳香','The gardener noticed a balmy scent from the flowering shrubs as she watered the path beside the greenhouse.','园丁给温室旁的小路浇水时，闻到开花灌木散发出芳香。','The gardener / noticed a balmy scent / from the flowering shrubs / as she watered the path / beside the greenhouse.','notice + 宾语；as 表示同时；from 引出气味来源。','The scent is sweet and soothing, matching the fragrance-related sense of balmy.')],
  mistakes:[m('The picnic was held on a freezing, windy night, which the guests described as balmy because their hands were numb.','The picnic was held on a mild, calm night, which the guests described as balmy.','balmy 描述暖和、平静、宜人的天气；寒冷大风与其相反。')],
  quiz:[q('balmy',1,1,'Balmy weather is generally?','warm, calm, and pleasant','freezing with violent winds','dark because the sun never rises','balmy 的常见天气义是温暖平静而舒适。'),q('balmy',2,2,'A balmy scent is?','sweet and pleasant','sharp and entirely scentless','a sound from an engine','balmy 也可表示芳香宜人。'),q('balmy',3,1,'Which evening could be called balmy?','a mild, still evening by the sea','a blizzard with icy gusts','a hot room filled with smoke','温和无风的海边夜晚符合 balmy。'),q('balmy',4,1,'The adjective is related to which soothing noun?','balm','bale','bawl','balmy 由 balm 加 -y 构成。')]});
D('balsam',{
  etymology:{origin:'balsam 经古英语 balsam、拉丁语 balsamum 和希腊语 balsamon 进入英语，最终关联古代表示芳香树脂的闪语词源；具体传播路径存在差异。',prefix:null,root:null,suffix:null,history:[],formationLogic:null,mnemonic:null,note:'balsam 可指芳香树脂，也可指产生芳香树脂或相似香味的植物；balm 是相关的缩短形式。',source:'Etymonline — https://www.etymonline.com/word/balsam'},
  contexts:[c('balsam.s1','植物 · 树脂','The herbalist warmed a small amount of balsam resin and mixed it with oil to make a fragrant salve.','草药师把少量香脂树脂加热，再与油混合制成芳香药膏。','The herbalist / warmed a small amount of balsam resin / and mixed it with oil / to make a fragrant salve.','warm 与 mix 并列；to make 表目的。','The resin is aromatic and used to prepare a salve, illustrating balsam as a fragrant resin.'),c('balsam.s2','园艺 · 植物','In late summer, the garden balsam flowered beside the fence, producing bright blossoms that attracted several pollinating insects.','夏末，花园里的凤仙类植物在篱笆旁开花，鲜艳的花朵吸引了几种传粉昆虫。','In late summer / the garden balsam / flowered beside the fence / producing bright blossoms / that attracted several pollinating insects.','时间状语前置；producing 分词说明结果；that 引导定语从句。','Garden balsam here names a flowering plant rather than the extracted aromatic resin.')],
  mistakes:[m('The botanist described balsam resin as a synthetic metal with no fragrance and no plant source.','The botanist described balsam resin as an aromatic substance produced by plants.','balsam resin 是植物来源的芳香树脂，不是无香的合成金属。')],
  quiz:[q('balsam',1,1,'Balsam resin is characteristically?','aromatic and resinous','a hard metal from a furnace','a slow dance song','balsam 的一义是芳香树脂。'),q('balsam',2,2,'Garden balsam refers to?','a flowering plant','a vehicle axle','a courtroom official','balsam 也可指产芳香树脂或有相似香气的植物。'),q('balsam',3,1,'Which related word is a shortened form historically linked to balsam?','balm','backlash','ballad','balm 是 balsam 的缩短形式。'),q('balsam',4,1,'A gardener planting balsam is most likely working with?','a flowering plant','a bottle of motor oil','a baroque painting','园艺场景中 balsam 指植物。')]});
D('banal',{
  etymology:{origin:'banal 于18世纪从法语 banal「平庸、常见」借入；法语词早先表示领主领地内共同使用的事物，来自 ban「公告、领主管辖」，后发展为人人皆有、缺乏新意。',prefix:null,root:null,suffix:null,history:[],formationLogic:null,mnemonic:null,note:'现代英语重在因过于熟悉而乏味、缺乏原创性。',source:'Etymonline — https://www.etymonline.com/word/banal'},
  contexts:[c('banal.s1','写作 · 陈词滥调','The reviewer found the opening banal because it began with the familiar claim that every journey starts with a single step.','评论者觉得开头很陈腐，因为它又从“千里之行始于足下”这句熟悉的话说起。','The reviewer / found the opening banal / because it began with the familiar claim / that every journey starts with a single step.','find + 宾语 + 形容词补语；because 引导原因；that 引导同位语从句。','The opening relies on an overused familiar saying, making banal mean lacking originality and boring.'),c('banal.s1','艺术 · 缺乏新意','Although the installation used expensive materials, its arrangement was banal and repeated images visitors had seen in many other galleries.','尽管这件装置使用昂贵材料，它的构图却平庸乏味，重复了游客在许多其他画廊见过的图像。','Although the installation used expensive materials / its arrangement / was banal / and repeated images / visitors had seen in many other galleries.','Although 引导让步；was 与 repeated 并列谓语；省略关系代词的定语从句修饰 images。','Expensive materials do not make a design original; the repeated imagery establishes banality.')],
  mistakes:[m('The novel’s plot was banal because no reader had ever encountered its original and surprising premise before.','The novel’s plot was original because no reader had encountered its surprising premise before.','banal 表示常见、缺乏新意；从未出现过的新颖构思应称 original。')],
  quiz:[q('banal',1,1,'A banal idea is one that is?','overused and lacking originality','completely unfamiliar and inventive','difficult to measure with a barometer','banal 指因过于熟悉而乏味、平庸。'),q('banal',2,1,'Why might a reviewer call a slogan banal?','It repeats a tired, familiar thought.','It introduces a surprising new argument.','It contains a rare scientific discovery.','重复陈词滥调体现 banal 的含义。'),q('banal',3,1,'Which adjective is closest to banal in this source sense?','trite','novel','azure','trite 也表示陈腐、老套。'),q('banal',4,1,'A banal opening is most likely?','a predictable opening readers have seen many times','a fresh opening that changes the genre','a list of unfamiliar chemical elements','陈腐、可预测的开头符合 banal。')]});
D('bandanna',{
  etymology:{origin:'bandanna 于18世纪从印地语 bandhnū 借入英语，指经扎染处理的布料或方巾；其词源与梵语 bandh「捆绑、系住」有关。',prefix:null,root:{text:'Sanskrit bandh',gloss:'捆绑、系住'},suffix:null,history:[],formationLogic:null,mnemonic:null,note:'bandanna 与 bandana 都是常见拼法。',source:'Etymonline — https://www.etymonline.com/word/bandanna'},
  contexts:[c('bandanna.s1','衣着 · 头巾','The cyclist tied a red bandanna around her head to keep dust out of her hair on the unpaved road.','骑行者把一条红色大手帕系在头上，避免在未铺设的道路上让灰尘沾到头发。','The cyclist / tied a red bandanna around her head / to keep dust out of her hair / on the unpaved road.','tie A around B；to keep 表目的；keep sth out of sth。','The square patterned cloth is worn around the head as a scarf or practical covering.'),c('bandanna.s1','服饰 · 颈部方巾','At the outdoor concert, Mateo folded his patterned bandanna into a triangle and wore it loosely around his neck.','露天音乐会上，马特奥把印花方巾折成三角形，松松地系在脖子上。','At the outdoor concert / Mateo / folded his patterned bandanna into a triangle / and wore it loosely / around his neck.','fold A into B；wore 与 folded 并列；loosely 修饰 wear。','Wearing the cloth around the neck shows the same handkerchief/scarf article in a second natural use.')],
  mistakes:[m('She put on a bandanna, a pair of leather boots, and a metal axle before walking outside.','She put on a bandanna, a pair of leather boots, and a warm jacket before walking outside.','bandanna 是可穿戴的方巾；axle 是机械车轴，不能作为衣物穿在身上。')],
  quiz:[q('bandanna',1,1,'A bandanna is commonly a?','square patterned cloth worn on the head or neck','large metal bar supporting wheels','formal song telling a story','bandanna 是印花大手帕或头巾。'),q('bandanna',2,1,'Which spelling is also common?','bandana','bandanae','bandanner','bandana 是 bandanna 的常见变体拼法。'),q('bandanna',3,1,'A cyclist may wear a bandanna to?','cover the head or keep dust away','make a wheel rotate','measure air pressure','方巾可包头并挡住灰尘。'),q('bandanna',4,1,'The source word is connected with a process involving?','tying cloth before dyeing','baking bread before boiling','lowering a stage curtain','bandanna 词源与扎染布料及“系绑”有关。')]});
D('banding',{
  etymology:{origin:'banding 是 band 加名词化动词后缀 -ing；band 作「条带」源于古诺尔斯语 band「带、束」，与 bind「绑」同族。不同专业语境进一步发展出分组和给鸟套环等义。',prefix:null,root:{text:'band',gloss:'带、条带；分组'},suffix:{text:'-ing',gloss:'构成动作或结果名词'},history:[],formationLogic:'band + -ing；指形成的条带，也指分组或套环活动。',mnemonic:null,note:'学校分组、材料条纹、鸟类环志是彼此不同的专业用法。',source:'Etymonline — https://www.etymonline.com/word/banding'},
  contexts:[c('banding.s1','设计 · 条纹装饰','The ceramic bowl’s blue banding was applied by hand, leaving a narrow stripe around its rim and two wider bands near the base.','这只陶碗的蓝色条纹是手工绘制的，碗沿有一道窄纹，靠近底部还有两道较宽的带状纹。','The ceramic bowl’s blue banding / was applied by hand / leaving a narrow stripe around its rim / and two wider bands near the base.','被动 was applied；leaving 分词表示结果；and 并列两个纹带。','The visible decorative strips are the pattern sense of banding.'),c('banding.s2','教育 · 能力分组','The school reviewed its banding policy after teachers found that students had been placed in ability groups on the basis of one test alone.','教师发现学生仅凭一次考试就被分入能力组后，学校重新审查了分组政策。','The school / reviewed its banding policy / after teachers found / that students had been placed in ability groups / on the basis of one test alone.','after 引导时间从句；that 引导 found 的宾语从句；被动 had been placed。','Ability groups make banding refer to sorting pupils into sets, a distinct education sense.')],
  mistakes:[m('The school called its banding policy a system in which every student stayed in one mixed class and no ability groups were formed.','The school called its mixed-class policy a system in which no ability bands were formed.','教育义 banding 是按能力把学生分组；所有学生都留在混合班与此含义相反。')],
  quiz:[q('banding',1,1,'Blue banding on a bowl refers to?','decorative stripes or bands','the bowl’s handle','a bird’s flight path only','banding 第一义是条纹或带状装饰。'),q('banding',2,2,'In a school, banding can mean?','sorting pupils into ability groups','painting every student’s shoes','forming a band that plays music only','教育领域的 banding 指按能力分组。'),q('banding',3,1,'Which object could visibly have banding?','a bowl with painted stripes','a plain document with no markings','a clear sky without clouds','碗上的彩色条纹属于 banding。'),q('banding',4,2,'A school reviewing its banding is considering how it?','groups students by ability','chooses its music for a dance','maintains a water reservoir','学校 banding policy 涉及能力分组方式。')]});
D('bandleader',{
  etymology:{origin:'bandleader 是 band「乐队」与 leader「领队」组合而成的复合名词；leader 由 lead「带领」加施事后缀 -er 构成，常指爵士或舞曲乐队的领奏者。',prefix:null,root:{text:'band + leader',gloss:'乐队 + 领队'},suffix:{text:'-er',gloss:'施事者'},history:[],formationLogic:'band + leader；在演奏中带领乐队的音乐家。',mnemonic:null,note:'bandleader 常见于爵士、摇摆乐或舞曲乐队；军乐队指挥更常称 bandmaster。',source:'Etymonline — https://www.etymonline.com/word/bandleader'},
  contexts:[c('bandleader.s1','音乐 · 爵士乐队','The bandleader counted off the opening bars, then signalled the brass section to enter after the piano solo.','乐队领队数出开头几小节，随后示意铜管组在钢琴独奏后加入。','The bandleader / counted off the opening bars / then signalled the brass section / to enter / after the piano solo.','count off 表示打拍起奏；signal someone to do；after 引导时间状语。','The musician directs the group’s performance and cues sections, the role of a jazz/dance bandleader.'),c('bandleader.s1','演出 · 现场指挥','During the final number, the bandleader raised one hand to cue the drums and kept the singers together through the ending.','最后一首曲子中，乐队领队举手提示鼓手进入，并带着歌手们合拍完成结尾。','During the final number / the bandleader / raised one hand / to cue the drums / and kept the singers together through the ending.','to cue 表目的；raised 与 kept 并列；keep + 宾语 + 形容词补语。','Cueing the band and coordinating the singers are specific leadership actions in performance.')],
  mistakes:[m('The bandleader ignored the musicians, gave no cues, and merely sold tickets outside the concert hall.','The bandleader directed the musicians and gave cues during the performance.','bandleader 是在演奏中带领乐队的音乐家，不是只在场外售票的人。')],
  quiz:[q('bandleader',1,1,'A bandleader in a jazz group typically?','leads the musicians and gives performance cues','sells travel guidebooks','maintains a ship’s armour','bandleader 负责带领爵士、舞曲等乐队。'),q('bandleader',2,1,'Which moment would show a bandleader at work?','signalling the brass section to enter','repairing the ballroom floor alone','calling one player a wild baboon','示意某声部进入是乐队领队的工作。'),q('bandleader',3,1,'Which role is more specifically associated with military or brass bands?','bandmaster','balloonist','backpacker','军乐或铜管乐队指挥常称 bandmaster。'),q('bandleader',4,1,'A bandleader is most likely a?','musician who leads a band','person who builds a backpack','scientist studying bacteria','bandleader 通常本身是带领乐队演奏的音乐家。')]});
D('bandmaster',{
  etymology:{origin:'bandmaster 由 band 与 master「负责人、主管」组成，指铜管乐队或军乐队的指挥；band 在此为音乐团体，master 表示负责领导的人。',prefix:null,root:{text:'band + master',gloss:'乐队 + 负责人'},suffix:null,history:[],formationLogic:'band + master；负责指挥乐队的人。',mnemonic:null,note:'与爵士、舞曲等乐队的 bandleader 意义相近，但 bandmaster 更常用于军乐或铜管乐队。',source:'Etymonline — https://www.etymonline.com/word/bandmaster'},
  contexts:[c('bandmaster.s1','音乐 · 铜管乐队','The bandmaster rehearsed the brass ensemble in the town hall, correcting the tempo before the musicians marched in the parade.','乐队指挥在市政厅排练铜管乐团，在乐手参加游行前纠正了速度。','The bandmaster / rehearsed the brass ensemble / in the town hall / correcting the tempo / before the musicians marched in the parade.','rehearse + 宾语；correcting 表伴随动作；before 引导时间从句。','The brass ensemble and rehearsal leadership identify the conductor sense of bandmaster.'),c('bandmaster.s1','军乐 · 训练指挥','At inspection, the bandmaster gave the military musicians a clear downbeat so every section began the march together.','检阅时，军乐队指挥给乐手打出清晰的第一拍，使各声部同时开始进行曲。','At inspection / the bandmaster / gave the military musicians a clear downbeat / so every section began the march together.','give someone a cue；so 引导结果；began 为过去式。','Leading military musicians and coordinating the march are characteristic bandmaster duties.')],
  mistakes:[m('The bandmaster managed a brass ensemble, but the word meant the owner of the hall who never directed the musicians.','The bandmaster directed the brass ensemble during rehearsal.','bandmaster 指管乐或军乐队指挥，不是场地所有者或经纪人。')],
  quiz:[q('bandmaster',1,1,'A bandmaster most commonly conducts?','a brass or military band','a group of courtroom jurors','a class studying botany','bandmaster 指管乐队或军乐队指挥。'),q('bandmaster',2,1,'What might a bandmaster give before a march begins?','a clear musical downbeat','a medical diagnosis','a bale of hay','指挥会给出起拍信号，帮助乐队同步。'),q('bandmaster',3,1,'Which title is more typical for the leader of a jazz dance band?','bandleader','bandmaster','baron','爵士或舞曲乐队领队通常称 bandleader。'),q('bandmaster',4,1,'In bandmaster, master means the person who?','directs or is in charge of the band','writes down every audience member’s name','plays only the slowest ballad','master 在复合词中指负责指挥或管理的人。')]});
D('banker',{
  etymology:{origin:'banker 约16世纪由 bank 加施事后缀 -er 构成，指经营银行或从事银行业务的人；bank「金融机构」经意大利语 banca、法语 banque 而来，原指放钱的桌台。',prefix:null,root:{text:'bank',gloss:'银行'},suffix:{text:'-er',gloss:'从事相关职业的人'},history:[],formationLogic:'bank + -er；从银行派生出银行业者。',mnemonic:null,note:'赌博语境中 banker 另指庄家或庄家持有的牌手。',source:'Etymonline — https://www.etymonline.com/word/banker'},
  contexts:[c('banker.s1','金融 · 银行业','The banker reviewed the small company’s cash-flow records before deciding whether its loan application met the branch’s lending rules.','银行职员在决定小公司的贷款申请是否符合分行放贷规定前，审核了它的现金流记录。','The banker / reviewed the small company’s cash-flow records / before deciding / whether its loan application met the branch’s lending rules.','review before deciding；whether 引导间接疑问句。','Reviewing a loan application is work performed by a financial professional, the principal source sense of banker.'),c('banker.s1','金融 · 客户服务','After the transfer was delayed, the banker traced the payment and explained which details the customer needed to confirm.','转账延迟后，银行职员追查了这笔付款，并说明客户需要确认哪些信息。','After the transfer was delayed / the banker / traced the payment / and explained / which details the customer needed to confirm.','after 引导时间从句；trace 与 explain 并列；which 引导间接疑问句。','The employee investigates a customer’s transaction as part of banking work.')],
  mistakes:[m('The banker examined loan applications at the lending desk, but the word meant a musician who conducted a brass band.','The bandmaster examined the brass musicians, while the banker handled loan applications.','banker 指银行业者；指挥管乐队的人是 bandmaster。')],
  quiz:[q('banker',1,1,'A banker works chiefly with?','financial services such as deposits and loans','the formal staging of a dance','cultivating barley in a field','banker 是银行业者，处理存款、贷款等事务。'),q('banker',2,1,'Which task most naturally belongs to a banker?','reviewing a customer’s loan application','leading the brass section into a march','recording a bird’s leg band','审核贷款申请是银行业务。'),q('banker',3,1,'In a casino game, banker can also refer to?','the player or house holding the bank','a person repairing a wheel axle','a buyer of travel books','banker 在赌博语境中可指庄家。'),q('banker',4,1,'The occupational suffix in banker is?','-er','-ish','-ness','bank + -er 形成表示从业者的名词。')]});
D('bankruptcy',{
  etymology:{origin:'bankruptcy 约1700年由 bankrupt 加抽象名词后缀 -cy 构成；bankrupt 源自意大利语 banca rotta「破裂的柜台」，比喻商人无力偿债。',prefix:null,root:{text:'bankrupt',gloss:'无力偿债的'},suffix:{text:'-cy',gloss:'构成状态或性质名词'},history:[],formationLogic:'bankrupt + -cy；指无力偿债的状态，也引申为彻底失败。',mnemonic:null,note:'法律破产义与比喻上的彻底失败需依语境区分。',source:'Etymonline — https://www.etymonline.com/word/bankruptcy'},
  contexts:[c('bankruptcy.s1','商业 · 法律程序','After six months of missed payments, the retailer filed for bankruptcy and asked the court to supervise the sale of its remaining assets.','连续六个月未能付款后，零售商申请破产，并请求法院监督出售其剩余资产。','After six months of missed payments / the retailer / filed for bankruptcy / and asked the court / to supervise the sale of its remaining assets.','file for bankruptcy 是固定法律表达；ask someone to do；to supervise 表目的。','The court-supervised handling of assets after inability to pay identifies the formal insolvency sense.'),c('bankruptcy.s2','比喻 · 彻底失败','The essay’s bankruptcy of evidence became clear when every statistic cited in its conclusion came from an unrelated survey.','结论中的每项统计都来自无关调查后，这篇文章证据匮乏的问题便显露无遗。','The essay’s bankruptcy of evidence / became clear / when every statistic cited in its conclusion / came from an unrelated survey.','bankruptcy of evidence 比喻根本缺乏；when 引导时间/条件从句；cited 为过去分词修饰 statistic。','The figurative phrase means a complete absence of a necessary quality, not legal insolvency.')],
  mistakes:[m('The firm paid every debt in full and continued operating normally, so it entered bankruptcy because it could not pay its obligations.','The firm could not pay its debts, so it filed for bankruptcy.','bankruptcy 法律义的关键是无力偿还债务；全额还债与仍然破产相矛盾。')],
  quiz:[q('bankruptcy',1,1,'A business enters bankruptcy when it?','cannot meet its debt obligations','has paid all debts and expanded safely','has changed the colour of its logo','bankruptcy 指无力偿债的法律程序或状态。'),q('bankruptcy',2,2,'A “bankruptcy of evidence” means?','a complete lack of evidence','a court sale of an office building','an abundance of reliable sources','比喻义表示某种事物彻底缺乏。'),q('bankruptcy',3,1,'Which phrase is standard in the legal sense?','file for bankruptcy','file in a bankruptcying','bankruptcy the court for','常用 file for bankruptcy 表示申请破产。'),q('bankruptcy',4,1,'The word is formed from bankrupt plus?','-cy','-ish','-ist','bankruptcy 由 bankrupt 和 -cy 构成。')]});
D('barbarian',{
  etymology:{origin:'barbarian 经中古拉丁语 barbarinus、拉丁语 barbarus 和希腊语 barbaros「外来、异族」进入英语；希腊语音拟外语听来不明的声音。',prefix:null,root:{text:'Greek barbaros',gloss:'外来者；异族'},suffix:null,history:[],formationLogic:null,mnemonic:null,note:'现代称人时往往冒犯；形容词义可指野蛮或未开化。',source:'Etymonline — https://www.etymonline.com/word/barbarian'},
  contexts:[c('barbarian.s1','历史 · 古典世界','The textbook explains that Greek writers once used barbarian for people whose language and customs differed from their own.','教材解释说，希腊作者过去用 barbarian 称语言和习俗不同于自己的民族。','The textbook / explains / that Greek writers once used barbarian / for people / whose language and customs differed from their own.','explain 后接 that 宾语从句；use A for B；whose 引导定语从句。','The historical discussion presents the old outsider label and its relative viewpoint, not a neutral modern identity.'),c('barbarian.s2','行为 · 粗野举止','The columnist called the vandal a barbarian after he smashed the public sculptures and threatened the museum staff.','专栏作者称破坏者为粗野之人，因为他砸毁了公共雕塑，还威胁博物馆工作人员。','The columnist / called the vandal a barbarian / after he smashed the public sculptures / and threatened the museum staff.','call + 宾语 + 名词补语；after 引导时间从句；并列谓语。','The destructive, threatening conduct supports the pejorative figurative description of a rude or wild person.')],
  mistakes:[m('The historian called the foreign-language speaker a barbarian as an objective modern scientific category that carries no prejudice.','The historian noted that ancient writers used barbarian as a prejudicial label for outsiders.','barbarian 作人称标签带有历史偏见，现代使用常冒犯；不应宣称它是中性的科学分类。')],
  quiz:[q('barbarian',1,1,'In classical usage, a barbarian was often someone?','from a culture or language outside one’s own','who held a formal bank loan','who sang only slow love songs','barbarian 历史上用来指与自身语言文化不同的外来者。'),q('barbarian',2,2,'Calling a person a barbarian today can sound?','insulting and prejudiced','like a neutral job title','like a compliment about careful manners','现代以 barbarian 称人常带贬义或冒犯。'),q('barbarian',3,1,'Which behaviour best fits the figurative insult?','smashing public art and threatening staff','carefully repairing a sculpture','quietly reading the museum guide','破坏公物并威胁他人符合粗野、暴力的贬义。'),q('barbarian',4,1,'The word’s Greek form was linked to?','speech that sounded unintelligible to listeners','a ring-shaped bread roll','a measure of air pressure','词源将其与外人语言听来像含混音声联系起来。')]});
D('barbaric',{
  etymology:{origin:'barbaric 于15世纪末经法语 barbarique 借入，源自拉丁语 barbaricus、希腊语 barbarikos「异族的、粗野的」；现代可指残酷暴烈，也可指粗豪华丽的风格。',prefix:null,root:{text:'Greek barbarikos',gloss:'异族的、粗野的'},suffix:null,history:[],formationLogic:null,mnemonic:null,note:'与 barbarous 近义但不完全相同；barbaric 有时也形容粗豪、缺少精致感的风格。',source:'Etymonline — https://www.etymonline.com/word/barbaric'},
  contexts:[c('barbaric.s1','冲突 · 残暴行为','The inquiry described the attack as barbaric because armed men beat unarmed villagers and burned their homes.','调查称这次袭击极其残暴，因为武装人员殴打手无寸铁的村民并焚烧他们的家园。','The inquiry / described the attack as barbaric / because armed men beat unarmed villagers / and burned their homes.','describe A as B；because 引导原因；beat 与 burned 并列。','Violence against unarmed residents makes barbaric mean cruel and savage.'),c('barbaric.s2','艺术 · 粗豪风格','The designer gave the hall a barbaric splendour with oversized bronze animals, raw stone pillars, and blazing red banners.','设计师用巨大的青铜兽像、粗犷石柱和鲜红旗帜，赋予大厅一种粗豪华丽的气势。','The designer / gave the hall a barbaric splendour / with oversized bronze animals / raw stone pillars / and blazing red banners.','give + 间接宾语 + 直接宾语；with 列举设计元素。','The vivid, rough, imposing decoration illustrates the less common sense of wild, unrefined grandeur rather than cruelty.')],
  mistakes:[m('The report called the deliberate beating of unarmed villagers a gentle and harmless act.','The report called the deliberate beating of unarmed villagers a barbaric act.','蓄意殴打无武装平民是残酷暴烈的行为；gentle and harmless 与事实相反。')],
  quiz:[q('barbaric',1,1,'A barbaric attack is?','extremely cruel or violent','carefully planned as a peaceful visit','a routine musical rehearsal','barbaric 的常见义是残暴、野蛮的。'),q('barbaric',2,2,'A “barbaric splendour” in an art review may describe?','rough, loud, richly imposing decoration','a plain unadorned white wall','a quiet legal hearing','barbaric 也可形容粗豪、喧闹而宏伟的风格。'),q('barbaric',3,1,'Which adjective often describes a cruel act?','barbaric','barometric','beaded','barbaric 可修饰残酷暴烈的行为。'),q('barbaric',4,1,'The source relates barbaric to a Greek adjective meaning?','like a foreigner or uncultured','a small ring-shaped bread','a soothing skin ointment','barbaric 通过希腊语 barbarikos 关联“外来、粗野”的旧义。')]});
D('barbarous',{
  etymology:{origin:'barbarous 经古法语 barbarous、拉丁语 barbarus 和希腊语 barbaros「外来、粗野」进入英语；英语中常强调残忍不人道，也可形容粗俗无礼的言行。',prefix:null,root:{text:'Greek barbaros',gloss:'外来、粗野'},suffix:null,history:[],formationLogic:null,mnemonic:null,note:'barbarous 与 barbaric 都可译作野蛮；前者常突出残酷或缺乏教养。',source:'Etymonline — https://www.etymonline.com/word/barbarous'},
  contexts:[c('barbarous.s1','历史 · 严酷惩罚','The historian called the punishment barbarous because prisoners were left without food in freezing cells for days.','历史学家称这种惩罚极其残酷，因为囚犯在冰冷牢房中几天得不到食物。','The historian / called the punishment barbarous / because prisoners were left without food / in freezing cells / for days.','call + 宾语 + 形容词补语；because 引导原因从句；被动 were left。','Depriving prisoners of food in freezing conditions is inhumane cruelty, the main sense of barbarous.'),c('barbarous.s2','礼仪 · 粗鲁无礼','The guest made a barbarous remark about the host’s accent and continued speaking over everyone at the table.','客人对主人口音说了句粗鲁的话，还在餐桌上不停打断别人。','The guest / made a barbarous remark / about the host’s accent / and continued speaking over everyone / at the table.','make a remark about；continue + -ing；and 连接并列动作。','The insulting comment and refusal to let others speak illustrate the uncultured, ill-mannered sense.')],
  mistakes:[m('The guards treated every prisoner humanely, provided warm meals, and described the conditions as barbarous.','The guards treated every prisoner humanely, provided warm meals, and described the conditions as humane.','公平照料、供应温餐体现 humane；barbarous 意味着残酷或不人道。')],
  quiz:[q('barbarous',1,1,'A barbarous punishment is?','cruel and inhumane','careful and merciful','a type of coloured glaze','barbarous 常指残忍、不人道。'),q('barbarous',2,2,'A barbarous remark is likely?','rude and uncultured','polite and carefully phrased','a line in a musical score','barbarous 也可形容粗鲁无礼的话语。'),q('barbarous',3,1,'Which action would a report call barbarous?','leaving prisoners to freeze without food','providing shelter and medical care','apologizing for a minor delay','让囚犯挨饿受冻是残酷行为。'),q('barbarous',4,1,'Which adjective emphasizes humane treatment, the opposite of barbarous?','merciful','barbaric','backbreaking','merciful 与残酷、不人道的 barbarous 相反。')]});
D('barefaced',{
  etymology:{origin:'barefaced 由 bare「无遮掩的」与 face「脸」组成，最初字面指没有遮面，后在17世纪发展出「公然、厚颜无耻」的比喻义。',prefix:null,root:{text:'bare + face',gloss:'无遮掩 + 脸'},suffix:{text:'-ed',gloss:'构成形容词'},history:[],formationLogic:'bare + face + -ed；从不遮脸引申为不加掩饰、无耻公开。',mnemonic:null,note:'barefaced lie 是常见搭配，强调谎言公然明显。',source:'Etymonline — https://www.etymonline.com/word/barefaced'},
  contexts:[c('barefaced.s1','沟通 · 公然谎言','The spokesperson offered a barefaced lie about the missing funds, even though the signed transfer record was already public.','尽管签署的转账记录早已公开，发言人仍对资金失踪一事公然撒谎。','The spokesperson / offered a barefaced lie / about the missing funds / even though the signed transfer record was already public.','offer a lie；even though 引导让步从句。','The publicly available record makes the lie conspicuously shameless and undisguised, the figurative sense.'),c('barefaced.s1','行为 · 厚颜无耻','In a barefaced attempt to avoid the fee, the contractor claimed that the completed repairs had never been requested.','承包商厚颜无耻地试图逃避费用，声称已经完成的维修从未有人要求过。','In a barefaced attempt to avoid the fee / the contractor / claimed / that the completed repairs had never been requested.','attempt to do；that 引导 claimed 的宾语从句；过去完成时被动。','The denial of a documented request is an open, shameless attempt rather than a hidden mistake.')],
  mistakes:[m('He openly disclosed the full record, admitted the error, and called his transparent apology barefaced.','He openly disclosed the full record, admitted the error, and offered a sincere apology.','barefaced 带有无耻、不加掩饰的负面评价；诚恳认错不符合这种描述。')],
  quiz:[q('barefaced',1,1,'A barefaced lie is one that is?','open and shameless','whispered so quietly nobody can hear','a true statement supported by records','barefaced 修饰 lie 时指公然、厚颜无耻的谎言。'),q('barefaced',2,1,'A barefaced attempt to evade a fee is?','an undisguised, shameless effort','a polite and fully transparent payment','an accidental delay caused by weather','barefaced 强调行为不加掩饰且厚颜无耻。'),q('barefaced',3,1,'Which action best fits barefaced?','denying a documented fact in public','admitting an error and correcting it','asking privately for clarification','公然否认已有证据的事实可称 barefaced。'),q('barefaced',4,1,'The literal image behind barefaced is a face that is?','uncovered','painted bright blue','hidden behind a curtain','bare + face 字面是无遮掩的脸，后引申为公然。')]});
D('baritone',{
  etymology:{origin:'baritone 经意大利语 baritono 和法语 baryton 进入英语，最终来自希腊语 barytonos「低沉的声音」；词根包含 barys「重、低」与 tonos「音调」。',prefix:null,root:{text:'Greek barys + tonos',gloss:'低沉 + 音调'},suffix:null,history:[],formationLogic:null,mnemonic:null,note:'baritone 可指男中音声部，也可指唱该声部的男性歌手。',source:'Etymonline — https://www.etymonline.com/word/baritone'},
  contexts:[c('baritone.s1','音乐 · 声部','The baritone entered after the tenor, adding a warmer lower line to the quartet without covering the bass.','男中音在男高音之后进入，为四重唱加入较温暖的低声部，但没有盖过男低音。','The baritone / entered after the tenor / adding a warmer lower line / to the quartet / without covering the bass.','enter after 表示后加入；adding 分词说明作用；without + 动名词。','Tenor, baritone, and bass are compared as adjacent male voice ranges; baritone lies between tenor and bass.'),c('baritone.s1','歌剧 · 歌手','The opera hired a baritone to sing the magistrate, whose rich middle-range voice suited the stern character.','歌剧院聘请一位男中音演唱地方法官，他浑厚的中音域嗓音很适合这个严厉角色。','The opera / hired a baritone / to sing the magistrate / whose rich middle-range voice / suited the stern character.','hire someone to do；whose 引导定语从句修饰 magistrate。','Here baritone refers to the singer who performs the male middle voice part.')],
  mistakes:[m('The singer was classified as a baritone because his voice was higher than a tenor and lower than a bass.','The singer was classified as a baritone because his voice was lower than a tenor and higher than a bass.','男中音音域低于男高音而高于男低音；原句把比较次序反过来了。')],
  quiz:[q('baritone',1,1,'A baritone voice lies between?','tenor and bass','soprano and alto only','whisper and silence','baritone 男中音处于男高音与男低音之间。'),q('baritone',2,1,'A baritone may be?','a male singer with a middle-range voice','a person who plays a very small flute','a conductor of a military band only','baritone 也指唱男中音声部的男性歌手。'),q('baritone',3,1,'Which singer would likely sing a baritone part?','a man with a voice below tenor and above bass','a singer with the highest soprano range','a drummer with no vocal part','男中音声部处于 tenor 与 bass 之间。'),q('baritone',4,1,'A baritone aria belongs most naturally to?','opera or vocal music','a gardening manual','a guidebook about trains','aria 是声乐作品，baritone 描述演唱声部。')]});
D('barley',{
  etymology:{origin:'barley 延续古英语 bære；其更早的日耳曼语来源不确定，可能与 bar「大麦」及表示作物或谷粒的古词族有关，因此不强行拆出现代词素。',prefix:null,root:null,suffix:null,history:[],formationLogic:null,mnemonic:null,note:'barley 作作物或谷物名通常不可数；单粒可说 a grain of barley。',source:'Etymonline — https://www.etymonline.com/word/barley'},
  contexts:[c('barley.s1','农业 · 谷物作物','The farmer planted barley on the cooler northern field because the crop tolerates conditions that would damage the neighbouring wheat.','农民在较凉爽的北边田地种植大麦，因为这种作物能耐受会损害邻田小麦的环境。','The farmer / planted barley / on the cooler northern field / because the crop tolerates conditions / that would damage the neighbouring wheat.','plant + 作物；because 引导原因；that 引导定语从句。','Barley as a crop plant is contrasted with neighbouring wheat.'),c('barley.s2','烹饪 · 谷粒','For the soup, add a handful of barley after the vegetables soften and simmer it until the grains become tender.','做这锅汤时，蔬菜变软后加入一把大麦粒，慢炖至谷粒变软。','For the soup / add a handful of barley / after the vegetables soften / and simmer it / until the grains become tender.','祈使句；after 和 until 引导时间状语从句；it 指 barley。','The recipe uses the edible grains of the plant, the second source sense.')],
  mistakes:[m('The recipe calls for one barley, a single countable item, to be added to the soup.','The recipe calls for a grain of barley to be added to the soup.','barley 通常是不可数谷物名；指一粒时用 a grain of barley。')],
  quiz:[q('barley',1,1,'Barley is a?','grain crop used for food and drink','type of flowering tree that bears lemons','small sea mammal','barley 是用于食物和饮料的大麦作物。'),q('barley',2,2,'In soup, barley usually refers to?','the edible grains of the plant','the plant’s root bark only','a type of room for formal dancing','第二义指用于汤、面包等的麦粒。'),q('barley',3,1,'What is the natural count phrase for one piece?','a grain of barley','a barley','one barleying','barley 不可数，单粒说 a grain of barley。'),q('barley',4,1,'Which drink is traditionally made from malted barley?','beer','lemonade','mineral water only','大麦芽用于酿造啤酒。')]});
D('barometric',{
  etymology:{origin:'barometric 由 barometer 加形容词后缀 -ic 构成；barometer 源自希腊语 baros「重量、压力」与 metron「测量工具」，原指测量大气压力的仪器。',prefix:null,root:{text:'Greek baros + metron',gloss:'压力 + 测量'},suffix:{text:'-ic',gloss:'构成形容词'},history:[],formationLogic:'barometer + -ic；表示与气压或气压计有关。',mnemonic:null,note:'barometric 几乎总用于气象或仪器语境；barometer 可比喻某种趋势的指标。',source:'Etymonline — https://www.etymonline.com/word/barometric'},
  contexts:[c('barometric.s1','气象 · 大气压力','The pilot checked the barometric reading before takeoff because a rapid pressure drop could signal a developing storm.','飞行员起飞前查看了气压读数，因为气压迅速下降可能预示风暴正在形成。','The pilot / checked the barometric reading / before takeoff / because a rapid pressure drop / could signal a developing storm.','check a reading；before 引导时间；because 引导原因；could signal 表示可能性。','The pressure measurement used to assess weather is directly related to atmospheric pressure.'),c('barometric.s1','测量 · 天气仪表','A barometric sensor inside the station recorded the pressure every minute and sent the data to the forecasting office.','气象站内的气压传感器每分钟记录一次气压，并把数据发送给预报办公室。','A barometric sensor / inside the station / recorded the pressure every minute / and sent the data / to the forecasting office.','record 与 send 并列过去式；every minute 表频率。','The sensor measures air pressure, showing barometric as “connected with the instrument or quantity.”')],
  mistakes:[m('The barometric sensor measured the room’s temperature, so its report was a reading of air pressure.','The barometric sensor measured air pressure, while a thermometer measured the room’s temperature.','barometric 指气压或气压计；温度应由 thermometer 测量。')],
  quiz:[q('barometric',1,1,'A barometric reading measures?','air pressure','the loudness of a song','the weight of a bale of hay','barometric 的核心是大气压力或其读数。'),q('barometric',2,1,'Which instrument is most closely related to barometric data?','a barometer','a thermometer only','a tenor’s tuning fork','barometer 测量气压，barometric 表示与之相关。'),q('barometric',3,1,'A rapid barometric pressure fall may warn of?','a developing storm','a new ballroom opening','a crop of barley being harvested','气压迅速下降可能预示天气变化或风暴。'),q('barometric',4,1,'The suffix -ic in barometric forms?','an adjective','a plural noun','a past-tense verb','-ic 常构成形容词。')]});
D('baron',{
  etymology:{origin:'baron 经古法语 baron、拉丁语 baro 进入英语，曾表示贵族或军事随从；其更早词源不确定。现代保留爵位义，也可比喻有巨大商业权势的人。',prefix:null,root:null,suffix:null,history:[],formationLogic:null,mnemonic:null,note:'爵位义与商业大亨义不同；女性对应词可为 baroness。',source:'Etymonline — https://www.etymonline.com/word/baron'},
  contexts:[c('baron.s1','历史 · 贵族爵位','The baron attended the coronation as a hereditary noble, although his family had lost most of its land generations earlier.','这位男爵以世袭贵族身份参加了加冕典礼，尽管他的家族几代前就失去了大部分土地。','The baron / attended the coronation / as a hereditary noble / although his family had lost most of its land / generations earlier.','attend as 表示以某身份出席；although 引导让步；过去完成时表示更早失地。','The coronation and hereditary noble status establish the historical rank sense.'),c('baron.s2','商业 · 行业巨头','The newspaper magnate became a media baron by acquiring regional stations and funding several investigative desks.','这位报业大亨通过收购地区电视台并资助多个调查报道部门，成为媒体巨头。','The newspaper magnate / became a media baron / by acquiring regional stations / and funding several investigative desks.','become a media baron；by 后接并列动名词说明方式。','Media ownership and substantial influence identify the figurative business-power sense.')],
  mistakes:[m('The historian described the businessman as a media baron because he had no influence, owned no outlets, and held no power in the industry.','The historian described the influential owner of several media outlets as a media baron.','比喻义 baron 指某行业中权势极大的大亨；无影响力且无资产与此矛盾。')],
  quiz:[q('baron',1,1,'A historical baron held?','a rank in the nobility','a medical degree in bacteriology','a certificate as a ballroom dancer','baron 的第一义是贵族爵位男爵。'),q('baron',2,2,'A “media baron” is?','a powerful figure in the media business','a stage curtain behind actors','a person hired to watch children for an hour','baron 比喻商业或行业中的权势人物。'),q('baron',3,1,'A baroness is related to which title?','baron','baritone','barley','baroness 是与 baron 对应的女性爵位称号。'),q('baron',4,2,'A business baron is likely to?','control substantial resources or influence','have no role in that industry','be a single grain of barley','比喻义强调行业巨头的权势和影响。')]});
D('baroque',{
  etymology:{origin:'baroque 于18世纪从法语 baroque「不规则」进入英语，通常追溯至葡萄牙语 barroco「不规则珍珠」，但更早来源不确定；艺术史义指17至18世纪的华丽繁复风格。',prefix:null,root:null,suffix:null,history:[],formationLogic:null,mnemonic:null,note:'形容词可中性描述巴洛克风格，也可贬义表示繁复过头、过分雕琢。',source:'Etymonline — https://www.etymonline.com/word/baroque'},
  contexts:[c('baroque.s1','艺术史 · 风格时期','The gallery arranged its baroque room around gilded frames, dramatic religious canvases, and a carved altar from the seventeenth century.','画廊以镀金画框、戏剧化的宗教油画和一座十七世纪雕刻祭坛来布置巴洛克展厅。','The gallery / arranged its baroque room / around gilded frames / dramatic religious canvases / and a carved altar from the seventeenth century.','arrange around 表示围绕某主题布置；并列名词列举展品。','The period, religious art, gilding, and dramatic decoration identify the historical Baroque style.'),c('baroque.s2','设计 · 繁复装饰','The architect chose baroque ornament for the hotel lobby, covering the ceiling with curling leaves, gold trim, and sculpted figures.','建筑师为酒店大厅采用巴洛克式装饰，在天花板上布满卷叶纹、金色饰边和雕塑人物。','The architect / chose baroque ornament for the hotel lobby / covering the ceiling / with curling leaves, gold trim, and sculpted figures.','choose ornament for；cover A with B；covering 分词说明装饰方式。','The elaborate and rich decoration demonstrates the source adjective “baroque” as an artistic style.'),
    c('baroque.s3','文体 · 过度雕琢','The editor cut the baroque sentence into two direct clauses because its nested phrases obscured the main finding.','编辑把那句过分雕琢的话拆成两个直接的分句，因为层层嵌套的短语遮蔽了主要发现。','The editor / cut the baroque sentence into two direct clauses / because its nested phrases / obscured the main finding.','cut A into B；because 引导原因；its 指 sentence。','Nested, showy wording that gets in the way of meaning supports the critical “overly elaborate” sense.')],
  mistakes:[m('The editor praised the baroque sentence for its short, plain wording and complete lack of ornament.','The editor praised the baroque sentence for its elaborate, richly ornamented wording.','baroque 描述繁复、装饰华丽的风格；简洁朴素与它相反。')],
  quiz:[q('baroque',1,1,'Baroque is the name of a major artistic style from which centuries?','the seventeenth and eighteenth','the fifth and sixth only','the twenty-first and twenty-second','baroque 风格盛行于17至18世纪。'),q('baroque',2,2,'A baroque interior is likely to have?','rich, elaborate ornament','bare walls and no decoration','only practical metal machinery','巴洛克风格常有华丽繁复的装饰。'),q('baroque',3,3,'A baroque sentence criticized by an editor may be?','overly elaborate and showy','brief and completely plain','unrelated to any writing','第三义带贬义，指过度雕琢、繁复。'),q('baroque',4,1,'The word’s proposed Portuguese source meant?','an imperfect pearl','a clear travel map','a military music band','其词源通常追溯至表示“不规则珍珠”的葡萄牙语，但更早来源未定。')]});
D('barrage',{
  etymology:{origin:'barrage 于19世纪中期从法语 barrage 借入，源自 barrer「设置障碍、封锁」；先指炮兵火力封锁，再引申为问题、评论等密集而连续的冲击。',prefix:null,root:{text:'French barrer',gloss:'设障、封锁'},suffix:null,history:[],formationLogic:null,mnemonic:null,note:'barrage 常与炮火或一连串问题、投诉、批评搭配。',source:'Etymonline — https://www.etymonline.com/word/barrage'},
  contexts:[c('barrage.s1','军事 · 炮火封锁','The infantry waited behind the ridge until the artillery barrage stopped and engineers confirmed that the road ahead was passable.','步兵在山脊后等待，直到炮火停止且工兵确认前方道路可以通行。','The infantry / waited behind the ridge / until the artillery barrage stopped / and engineers confirmed / that the road ahead was passable.','wait until；until 引导时间从句；confirm 后接 that 宾语从句。','The artillery barrage is concentrated gunfire that suppresses or blocks movement.'),c('barrage.s2','媒体 · 连续提问','The minister faced a barrage of questions about the contract as reporters pressed for details she had not yet released.','部长面对有关合同的一连串提问，记者不断追问她尚未公布的细节。','The minister / faced a barrage of questions about the contract / as reporters pressed for details / she had not yet released.','a barrage of questions 是固定搭配；as 引导同时发生的情境；省略关系代词修饰 details。','The rapid succession of reporters’ questions is the figurative “large number all at once” sense.')],
  mistakes:[m('The spokesperson received one quiet question, answered it, and described the exchange as a barrage of hundreds of attacks.','The spokesperson received a barrage of hundreds of questions from reporters.','barrage 暗示密集大量的连续来袭；仅一个安静问题不是 barrage。')],
  quiz:[q('barrage',1,1,'An artillery barrage is?','a concentrated burst of gunfire','a single harmless rain drop','a quiet musical duet','barrage 的军事义是集中、密集的炮火。'),q('barrage',2,2,'A barrage of questions means?','many questions arriving rapidly','one question asked once','a written answer with no questions','比喻义指一连串同时涌来的问题。'),q('barrage',3,1,'Which phrase is natural?','a barrage of complaints','a barrage in one question','a barrage to a question at','常见表达是 a barrage of questions/complaints。'),q('barrage',4,2,'If a speaker faces a barrage from reporters, the speaker is?','being confronted with many rapid questions','waiting alone in a silent room','leading a brass band','记者集中连续提问构成 barrage。')]});
D('barrelful',{
  etymology:{origin:'barrelful 由 barrel「桶」与 -ful「足以装满的量」构成；复数常写 barrelfuls，也可见 barrelsful。该词既可指一桶的容量，也可非正式指大量。',prefix:null,root:{text:'barrel',gloss:'桶'},suffix:{text:'-ful',gloss:'表示容器装满的量'},history:[],formationLogic:'barrel + -ful；从容器容量引申为很多。',mnemonic:null,note:'名词作量词时用 a barrelful of；形容词短语 a barrel full of 中 full 分开写。',source:'Etymonline — https://www.etymonline.com/word/barrelful'},
  contexts:[c('barrelful.s1','农场 · 容量','At the cider press, the family collected a barrelful of apples from the orchard before sorting the bruised fruit.','在榨苹果酒的机器旁，这家人在挑出碰伤的水果前，从果园收了一桶苹果。','At the cider press / the family / collected a barrelful of apples / from the orchard / before sorting the bruised fruit.','a barrelful of + 物品表示一桶之量；before + 动名词。','The apples fill one barrel, establishing the literal container-capacity sense.'),c('barrelful.s2','会话 · 大量','We had a barrelful of problems during the launch, from late parts to a software fault, but the team resolved each one.','发布期间我们遇到一大堆问题，从零件延迟到软件故障都有，但团队逐一解决了。','We / had a barrelful of problems during the launch / from late parts to a software fault / but the team resolved each one.','a barrelful of problems 是非正式夸张量词；from...to 列举范围；but 表转折。','A variety of launch problems makes barrelful an informal expression for a great deal.')],
  mistakes:[m('The recipe asked for a barrelful of sugar, meaning exactly one teaspoon for the entire batch.','The recipe asked for a teaspoon of sugar, not a barrelful.','barrelful 是整桶的量或夸张的大量，不可能表示一茶匙。')],
  quiz:[q('barrelful',1,1,'A barrelful of oil is?','the amount that fills one barrel','a single drop of oil','a metal tool for measuring temperature','barrelful 的字面义是装满一桶的量。'),q('barrelful',2,2,'“A barrelful of excuses” informally means?','a very large number of excuses','one carefully chosen excuse','no explanation at all','比喻义表示数量很多。'),q('barrelful',3,1,'Which grammar pattern is natural?','a barrelful of apples','a barrelful apples','barrelful to apples','名词 barrelful 后常接 of + 名词。'),q('barrelful',4,1,'How is the noun phrase different from “a barrel full of water”?','barrelful is one quantity noun; barrel full has separate full','they are both verbs','barrelful refers only to an empty barrel','barrelful 是量词名词；a barrel full of 中 full 单独作形容词。')]});
D('barrenness',{
  etymology:{origin:'barrenness 由 barren 加名词后缀 -ness 构成；barren 经中古英语 barain、古法语 baraigne 进入英语，原指不育或不结果，后引申为贫瘠和缺乏成果。',prefix:null,root:{text:'barren',gloss:'贫瘠、不育、无成果'},suffix:{text:'-ness',gloss:'构成状态名词'},history:[],formationLogic:'barren + -ness',mnemonic:null,note:'指人的生育能力时可能冒犯或过时；描述土壤、情节、想法时较中性。',source:'Etymonline — https://www.etymonline.com/word/barrenness'},
  contexts:[c('barrenness.s1','农业 · 土壤贫瘠','The barrenness of the rocky soil forced the growers to add compost and install irrigation before planting vegetables.','岩石土壤的贫瘠迫使种植者在种菜前先加入堆肥并安装灌溉设施。','The barrenness of the rocky soil / forced the growers / to add compost / and install irrigation / before planting vegetables.','the barrenness of；force someone to do；并列 add、install。','Poor, unproductive ground makes barrenness mean inability to produce crops.'),c('barrenness.s2','文学 · 内容空洞','Critics noted the barrenness of the plot: its characters faced no consequences, and no decision changed the story’s direction.','评论家指出情节空洞：角色无需承担任何后果，也没有任何决定改变故事走向。','Critics / noted the barrenness of the plot / its characters faced no consequences / and no decision changed the story’s direction.','冒号引出说明；分号可并列；此处用逗号及 and 连接后续解释。','The absence of consequences and meaningful developments is a lack of ideas or results, a figurative sense.')],
  mistakes:[m('The barrenness of the soil produced abundant healthy crops without water or nutrients.','The barrenness of the soil produced almost no crops without irrigation or nutrients.','贫瘠的土壤不能正常出产作物；丰收与 barrenness 的土地义矛盾。')],
  quiz:[q('barrenness',1,1,'The barrenness of a field means?','the land is unable to produce crops well','the soil is rich and highly productive','the field has been paved for dancing','barrenness 指土地贫瘠、无产出。'),q('barrenness',2,2,'The barrenness of a plot suggests it has?','few ideas, developments, or meaningful results','many surprising events and consequences','a large number of healthy crops','比喻义是缺少想法或成果、内容空洞。'),q('barrenness',3,1,'Which context best fits the figurative sense?','a critic says a novel has no real development','a farmer adds nutrients to poor soil','a gardener waters a dry field','小说缺乏发展对应情节空洞。'),q('barrenness',4,1,'Which suffix forms the state noun barrenness?','-ness','-ist','-ic','barren + -ness 构成表示状态的名词。')]});
D('barricade',{
  etymology:{origin:'barricade 经法语 barricade 进入英语，源自 barrique「木桶」；早期人们把木桶装土或石块横在道路上作临时防御，后成为一般路障和设障动词。',prefix:null,root:{text:'French barrique',gloss:'木桶'},suffix:null,history:[],formationLogic:null,mnemonic:null,note:'可作名词「路障」，也可作动词「设障封锁」。',source:'Etymonline — https://www.etymonline.com/word/barricade'},
  contexts:[c('barricade.s1','安全 · 临时路障','Police placed a barricade across the flooded road and directed drivers toward a higher route around the river.','警方在被淹的道路上设置路障，并指引司机绕河改走较高的路线。','Police / placed a barricade across the flooded road / and directed drivers / toward a higher route / around the river.','place a barricade across；并列谓语 placed、directed。','A temporary barrier physically blocks passage across the road.'),c('barricade.s2','防护 · 封住入口','The residents barricaded the basement door with sandbags when water began seeping into the lower hallway.','水开始渗入下层走廊时，居民用沙袋堵住了地下室的门。','The residents / barricaded the basement door with sandbags / when water began seeping / into the lower hallway.','barricade + 宾语 + with；when 引导时间从句；begin + -ing。','The verb means to block a passage by building or placing a barrier.')],
  mistakes:[m('The crew barricaded the emergency exit by removing every obstacle and leaving the doorway fully open.','The crew barricaded the emergency exit by placing a barrier across the doorway.','barricade 是用障碍物封住通道；移走障碍、保持门敞开与该动词相反。')],
  quiz:[q('barricade',1,1,'A barricade across a road is?','a temporary barrier blocking passage','a decorative stripe on a bowl','a piece of cloth for the head','barricade 名词是临时障碍物或路障。'),q('barricade',2,2,'To barricade a door is to?','block it with a barrier','paint it blue','measure the air pressure near it','barricade 作动词表示设障封住入口。'),q('barricade',3,1,'Which phrase is grammatical?','barricade the doorway with sandbags','barricade to the doorway from sandbags','barricade the doorway at sandbags it','barricade something with something 是自然结构。'),q('barricade',4,1,'The word’s early physical barriers were often made from?','barrels or similar objects filled with material','thin sheets of musical paper','a single stalk of barley','barricade 词源与用木桶装土、石设障有关。')]});
D('barter',{
  etymology:{origin:'barter 约16世纪经古法语 barater 进入英语，早期可表示欺骗、讨价还价或交换；其更早来源不确定，现代核心义是不用货币直接交换商品或服务。',prefix:null,root:null,suffix:null,history:[],formationLogic:null,mnemonic:null,note:'barter 可作制度名词或动词；常见结构 barter A for B。',source:'Etymonline — https://www.etymonline.com/word/barter'},
  contexts:[c('barter.s1','经济 · 物物交换','In the remote village, families relied on barter for basic goods because the nearest bank and cash machine were several hours away.','在偏远村庄，居民依靠以物易物换取生活用品，因为最近的银行和取款机都在数小时路程之外。','In the remote village / families / relied on barter for basic goods / because the nearest bank and cash machine / were several hours away.','rely on barter；because 引导原因从句；bank and cash machine 复数谓语 were。','The lack of cash access explains a system of direct exchange instead of money.'),c('barter.s2','交易 · 以物易物','The carpenter bartered two repaired chairs for a basket of apples rather than accepting cash from the orchard owner.','木匠用修好的两把椅子换了一篮苹果，而没有收果园主人的现金。','The carpenter / bartered two repaired chairs for a basket of apples / rather than accepting cash / from the orchard owner.','barter A for B；rather than 后接动名词。','The verb explicitly exchanges goods for other goods without money.')],
  mistakes:[m('The carpenter bartered two chairs for cash, meaning that no goods or services were exchanged.','The carpenter sold two chairs for cash.','barter 强调不用钱、以货换货；用现金付款称 sell rather than barter。')],
  quiz:[q('barter',1,1,'Barter is trade in which people?','exchange goods or services without money','borrow money at a bank','pay only with credit cards','barter 指不使用货币的物品或服务交换。'),q('barter',2,2,'The carpenter bartered chairs for apples. What did the carpenter receive?','apples','cash from the bank','a theatre ticket','barter A for B 中 for 后是换得的物品。'),q('barter',3,1,'Which sentence uses barter as a verb?','They bartered fish for cloth.','They borrowed money to buy fish.','They measured the fish with a barometer.','bartered 表示把鱼换成布。'),q('barter',4,1,'Which trade is barter rather than a cash sale?','trading a basket of grain for a repaired tool','paying cash for a repaired tool','depositing wages in a bank','用谷物直接换工具是不经货币的物物交换。')]});
D('basalt',{
  etymology:{origin:'basalt 于18世纪经法语、拉丁语进入英语，源自拉丁语 basaltes「玄武岩」；古代词源路径不确定，可能关联埃塞俄比亚地名或古代岩石名。',prefix:null,root:null,suffix:null,history:[],formationLogic:null,mnemonic:null,note:'basalt 是深色细粒火山岩，常构成海洋地壳和大型熔岩流。',source:'Etymonline — https://www.etymonline.com/word/basalt'},
  contexts:[c('basalt.s1','地质 · 火山岩','The geologists sampled dark basalt along the coast, where ancient lava had cooled into a hard, fine-grained rock.','地质学家在海岸采集深色玄武岩；古代熔岩在那里冷却成坚硬的细粒岩石。','The geologists / sampled dark basalt along the coast / where ancient lava / had cooled / into a hard, fine-grained rock.','where 引导地点定语从句；过去完成时 had cooled 表示先发生的地质过程。','Dark volcanic lava cooled into a fine-grained rock, defining basalt.'),c('basalt.s1','地质 · 海洋地壳','A cross-section of the ocean floor showed basalt beneath the sediment, confirming that the crust had formed from cooled volcanic material.','海底剖面显示沉积物下方是玄武岩，证实地壳由冷却的火山物质形成。','A cross-section of the ocean floor / showed basalt beneath the sediment / confirming / that the crust had formed / from cooled volcanic material.','show + 宾语；confirming 分词表示证据结果；that 引导宾语从句。','Basalt under ocean sediments fits its geological role as a major crustal rock.')],
  mistakes:[m('The geologist identified the pale, coarse-grained rock as basalt formed from compacted beach shells rather than lava.','The geologist identified the dark, fine-grained rock as basalt formed from cooled lava.','basalt 通常是深色、細粒火山岩；由貝殼壓實形成的是石灰岩一類。')],
  quiz:[q('basalt',1,1,'Basalt is a?','dark, fine-grained volcanic rock','soft textile used to make a bandanna','sweet ring-shaped bread','basalt 指深色细粒的火山岩。'),q('basalt',2,1,'Basalt commonly forms when?','lava cools','hay is tied into a bale','a ballroom floor is polished','玄武岩由熔岩冷却形成。'),q('basalt',3,1,'Which setting often contains basalt?','oceanic crust','a cotton clothing shop','a city bank vault','玄武岩是海洋地壳的主要岩石之一。'),q('basalt',4,1,'Which adjective is derived from basalt?','basaltic','barbaric','barometric','basaltic 是对应形容词。')]});
D('basaltic',{
  etymology:{origin:'basaltic 由 basalt 加形容词后缀 -ic 构成，表示由玄武岩组成或具有玄武岩特征；名词 basalt 的词源本身较不确定。',prefix:null,root:{text:'basalt',gloss:'玄武岩'},suffix:{text:'-ic',gloss:'构成形容词'},history:[],formationLogic:'basalt + -ic',mnemonic:null,note:'英语中名词 basalt 常重音在首音节，形容词 basaltic 常见重音后移。',source:'Etymonline — https://www.etymonline.com/word/basaltic'},
  contexts:[c('basaltic.s1','地质 · 岩层成分','The survey mapped a basaltic layer beneath the valley floor, tracing it to an ancient eruption from a nearby volcanic vent.','勘测绘出了山谷地表下方的一层玄武岩，并把它追溯到附近火山口的一次古代喷发。','The survey / mapped a basaltic layer / beneath the valley floor / tracing it / to an ancient eruption / from a nearby volcanic vent.','map a layer；tracing 分词说明地质调查过程；trace A to B。','The layer consists of basalt formed by volcanic activity, matching the compositional adjective.'),c('basaltic.s1','地质 · 岩石特征','Because the sample was basaltic, it was dark and fine-grained rather than pale and full of large crystals.','由于样本具有玄武岩特征，它呈深色、颗粒细小，而不是颜色浅且含有大晶体。','Because the sample was basaltic / it was dark and fine-grained / rather than pale / and full of large crystals.','Because 引导原因；rather than 连接对照的形容词短语。','Dark, fine texture is a characteristic comparison with basaltic rock.')],
  mistakes:[m('The field note called the pale quartz vein basaltic, although it consisted of clear crystals and contained no basalt.','The field note called the dark, fine-grained lava flow basaltic.','basaltic 表示由玄武岩组成或像玄武岩；纯石英脉不符合其成分或外观。')],
  quiz:[q('basaltic',1,1,'A basaltic rock is?','made of or resembling basalt','made only from paper and cloth','a legal document about insolvency','basaltic 指由玄武岩组成或具有玄武岩特征。'),q('basaltic',2,1,'A basaltic layer is most likely linked with?','cooled volcanic material','a ballroom dance class','a grain crop harvested in spring','玄武岩地层通常与火山物质冷却有关。'),q('basaltic',3,1,'Which adjective comes from basalt?','basaltic','balsamic','ballistic','basalt + -ic 构成 basaltic。'),q('basaltic',4,1,'Compared with many pale crystalline rocks, basaltic rock is often?','dark and fine-grained','bright blue and soft','made of woven reeds','玄武岩常呈深色、细粒。')]});
D('bask',{
  etymology:{origin:'bask 约14世纪出现，来自古诺尔斯语 baðask，字面约为「洗浴、给自己沐浴」，后来发展为舒适地享受阳光、温暖或赞誉。',prefix:null,root:{text:'Old Norse baðask',gloss:'洗浴、沐浴'},suffix:null,history:[],formationLogic:null,mnemonic:null,note:'bask in 可接阳光、温暖、赞美或成功；不能与只表示晒太阳的 sunbathe 完全互换。',source:'Etymonline — https://www.etymonline.com/word/bask'},
  contexts:[c('bask.s1','休息 · 晒太阳','The seal climbed onto a flat rock to bask in the afternoon sun while the tide receded around the pool.','潮水在水池周围退去时，海豹爬上平坦的岩石，享受午后的阳光。','The seal / climbed onto a flat rock / to bask in the afternoon sun / while the tide receded / around the pool.','climb onto；to bask 表目的；while 引导同时发生的背景动作。','Resting in warm sunlight is the literal, physical sense of bask.'),c('bask.s2','成就 · 沉浸赞誉','After the team’s invention won the prize, the researchers basked in public praise for several weeks.','团队的发明获奖后，研究人员在数周内沉浸于公众赞誉之中。','After the team’s invention won the prize / the researchers / basked in public praise / for several weeks.','After 引导时间从句；bask in + 抽象名词；for 表持续时间。','Public praise is an enjoyable feeling rather than literal heat, demonstrating the figurative sense.')],
  mistakes:[m('After the award, the scientist basked in criticism and said she felt delighted by every hostile review.','After the award, the scientist basked in praise and said she felt delighted by the recognition.','bask in 通常表示享受温暖、赞誉或成功；敌意批评不是令人愉悦的 praise。')],
  quiz:[q('bask',1,1,'A cat basking on a windowsill is?','enjoying the warmth of the sun','building a nest in water','arguing with a visitor','bask 第一义是躺着享受阳光暖意。'),q('bask',2,2,'To bask in praise is to?','enjoy being praised','avoid every compliment','criticize the people who praised you','bask in praise 表示沉浸、享受赞誉。'),q('bask',3,1,'Which preposition appears in the usual pattern?','bask in the sunshine','bask at the sunshine to','bask for of sunshine','常见搭配是 bask in sunshine/praise。'),q('bask',4,2,'Winning the award allowed the team to bask in?','the success and recognition','a cold swimming pool only','a shortage of evidence','获奖带来成功和认可，适合引申义 bask。')]});
D('basketmaking',{
  etymology:{origin:'basketmaking 由 basket「篮子」与 making「制作」构成复合名词，字面指编制篮子的手艺或活动；basket 与 make 的词源各自独立，不额外假设词根关系。',prefix:null,root:{text:'basket + making',gloss:'篮子 + 制作'},suffix:null,history:[],formationLogic:'basket + making；表示制作篮子的技艺。',mnemonic:null,note:'basketmaking 指手艺或活动；basketry 偏技艺类别，basketwork 偏编织成品。',source:'Etymonline — https://www.etymonline.com/word/basketmaking'},
  contexts:[c('basketmaking.s1','手工 · 编篮教学','At the community workshop, the instructor taught basketmaking by showing how to soak willow rods and weave them around a sturdy base.','社区工坊里，老师演示如何浸泡柳条并围绕结实的底座编织，从而教授编篮。','At the community workshop / the instructor / taught basketmaking / by showing how to soak willow rods / and weave them around a sturdy base.','teach an activity；by + 动名词说明方法；how to 后并列 soak、weave。','Soaking rods and weaving a base are steps in the craft of making baskets.'),c('basketmaking.s1','手艺 · 制作活动','The museum offers basketmaking classes where visitors can finish a small willow container and take it home.','博物馆开设编篮课程，游客可以完成一个小柳条篮并把它带回家。','The museum / offers basketmaking classes / where visitors can finish a small willow container / and take it home.','where 引导定语从句；finish 与 take 并列。','The class is about the activity and skill of producing woven baskets.')],
  mistakes:[m('She enrolled in basketmaking to learn how to tune a piano, bend metal gears, and repair a barometer.','She enrolled in basketmaking to learn how to weave strips into baskets.','basketmaking 是编篮手艺，不教授调钢琴或修理机械。')],
  quiz:[q('basketmaking',1,1,'Basketmaking is the craft of?','weaving materials into baskets','composing a slow love song','measuring air pressure','basketmaking 指编织篮子的手艺。'),q('basketmaking',2,1,'Which material might a basketmaker weave?','willow rods','a brass trumpet mouthpiece','a layer of basalt','柳条常用于编篮。'),q('basketmaking',3,1,'Basketmaking most directly names?','an activity or craft','a single finished basket only','a type of cloth worn as a scarf','它指制作篮子的活动或技艺。'),q('basketmaking',4,1,'Which related word more often names the resulting woven objects?','basketwork','barometric','bankruptcy','basketwork 更偏指编织物成品。')]});
D('basketry',{
  etymology:{origin:'basketry 由 basket 加集合或技艺名词后缀 -ry 构成，指编篮的手艺，也可集合指篮子等编织制品；basket 的更早词源不确定。',prefix:null,root:{text:'basket',gloss:'篮子'},suffix:{text:'-ry',gloss:'表示活动、技艺或集合'},history:[],formationLogic:'basket + -ry；从篮子派生出编篮技艺及其制品总称。',mnemonic:null,note:'basketry 可侧重编织技艺，也可统称编织制品；basketwork 更突出成品材料。',source:'Etymonline — https://www.etymonline.com/word/basketry'},
  contexts:[c('basketry.s1','手工 · 传统技艺','The community centre invited an elder to teach basketry, demonstrating how to split reeds and weave a tight base.','社区中心邀请一位长者教授编篮技艺，示范如何劈开芦苇并编出紧实的底部。','The community centre / invited an elder / to teach basketry / demonstrating how to split reeds / and weave a tight base.','invite someone to do；demonstrating 分词补充教学内容；how to 后并列动词。','Teaching the practical skill of preparing and weaving reeds is the craft sense of basketry.'),c('basketry.s2','博物馆 · 编织制品','The museum displayed basketry from several regions, comparing differences in fibre, pattern, and the shape of each finished vessel.','博物馆展出了几个地区的编织品，并比较纤维、纹样和每件成品器形的差异。','The museum / displayed basketry from several regions / comparing differences / in fibre, pattern, and the shape / of each finished vessel.','display + 集合名词；comparing 分词说明展览的比较内容。','The displayed collection of woven objects uses basketry as a collective name for the products.')],
  mistakes:[m('The museum labeled a carved basalt statue “basketry” because it had been sculpted from solid volcanic rock.','The museum labeled a woven reed container “basketry.”','basketry 指编篮技艺或编织制品；实心石雕不是编织物。')],
  quiz:[q('basketry',1,1,'Basketry is the craft of?','weaving baskets and similar items','writing legal contracts','tuning the pressure of a barometer','basketry 指编织篮子的手艺。'),q('basketry',2,2,'A museum’s collection of basketry may contain?','woven baskets and related objects','only metal gears and axles','a set of musical ballads','basketry 也可集合指编织制品。'),q('basketry',3,1,'Which material might be used in traditional basketry?','split reeds','liquid basalt','a steel bayonet','芦苇条常用于编篮。'),q('basketry',4,1,'Which term more specifically emphasizes the finished woven material?','basketwork','basketmaking','bankruptcy','basketwork 偏成品编织物；basketmaking 是制作活动。')]});
D('basketwork',{
  etymology:{origin:'basketwork 由 basket 与 work「制作物、工艺」组成，指用藤条、柳枝等编成的材料、构件或制品；构词透明，无需假设额外词根。',prefix:null,root:{text:'basket + work',gloss:'篮子 + 制成物'},suffix:null,history:[],formationLogic:'basket + work；由编篮技术制作的材料和成品。',mnemonic:null,note:'通常不可数；修饰家具时可说 a basketwork chair。',source:'Etymonline — https://www.etymonline.com/word/basketwork'},
  contexts:[c('basketwork.s1','家居 · 编织家具','The conservator repaired the basketwork seat of the old chair, replacing two split reeds while preserving the original frame.','修复师修好了旧椅子的编织座面，换掉两根裂开的藤条，同时保留原来的框架。','The conservator / repaired the basketwork seat / of the old chair / replacing two split reeds / while preserving the original frame.','repair the seat；replacing 分词说明方式；while preserving 表同时进行的保护。','The seat is made from woven strips rather than solid wood, showing the material sense of basketwork.'),c('basketwork.s1','工艺 · 编织隔屏','A lightweight basketwork screen divided the reading corner from the rest of the room without blocking the daylight.','一面轻质编织隔屏把阅读角与房间其他部分隔开，却没有挡住日光。','A lightweight basketwork screen / divided the reading corner from the rest of the room / without blocking the daylight.','divide A from B；without + 动名词。','The woven screen is an object made from flexible strips, a natural basketwork product.')],
  mistakes:[m('The chair’s basketwork seat was a solid sheet of unbroken marble with no woven strands.','The chair’s basketwork seat was woven from narrow cane strips.','basketwork 指藤条、细枝等编织材料或物品；整块大理石不属于编织物。')],
  quiz:[q('basketwork',1,1,'Basketwork is made by?','weaving strips such as cane or twigs','casting a solid block of marble','boiling bread before baking','basketwork 是用藤条、细枝等编织的材料或物品。'),q('basketwork',2,1,'Which object could have a basketwork seat?','a woven cane chair','a steel battleship','a stone statue','藤编椅的座面是 basketwork。'),q('basketwork',3,1,'Basketwork most often refers to?','the finished woven material or object','the act of teaching a class only','a legal process for unpaid debts','它偏指编织材料或编织成品。'),q('basketwork',4,1,'Which related word names the activity of weaving baskets?','basketmaking','barrenness','ballroom','basketmaking 指制作篮子的活动。')]});
D('bast',{
  etymology:{origin:'bast 延续古英语 bæst，是一种广泛见于日耳曼语的词，指椴树等树木内层的韧皮和纤维；该词族的更早起源不确定。',prefix:null,root:null,suffix:null,history:[],formationLogic:null,mnemonic:null,note:'植物材料名；不可与粗口或其他同形词义混淆。',source:'Etymonline — https://www.etymonline.com/word/bast'},
  contexts:[c('bast.s1','植物纤维 · 绳索','Workers peeled bast from the inner bark of the young trees and twisted the fibres into rough cord for tying bundles.','工人从幼树的内层树皮剥下韧皮，把纤维搓成粗绳，用来捆扎物品。','Workers / peeled bast from the inner bark / of the young trees / and twisted the fibres / into rough cord / for tying bundles.','peel material from；并列谓语 peeled、twisted；for + 动名词说明用途。','The peeled inner bark and its usable fibres define the botanical material sense of bast.'),c('bast.s1','手工 · 编织材料','The craftworker soaked bast fibres until they softened, then wove them into a durable mat for the workshop floor.','手工艺者把韧皮纤维浸泡到变软，再将它们编成耐用的工坊地垫。','The craftworker / soaked bast fibres / until they softened / then wove them / into a durable mat / for the workshop floor.','soak until；then 表顺序；weave something into something。','The fibres come from fibrous inner bark and can be processed into rope or matting.')],
  mistakes:[m('The botanist identified bast as the smooth outer metal coating of a tree, containing no plant fibres.','The botanist identified bast as the fibrous inner bark of a tree.','bast 指树木内层的纤维状树皮，不是金属涂层或光滑外皮。')],
  quiz:[q('bast',1,1,'Bast is the?','fibrous inner bark of certain trees','outer metal covering on a ship','singer’s low vocal range','bast 指树木的韧皮或内层纤维树皮。'),q('bast',2,1,'Bast fibres have traditionally been used to make?','cord and matting','glass windows','barometric sensors','韧皮纤维可制绳索和席垫。'),q('bast',3,1,'Where is bast found in a tree?','in the inner fibrous bark','inside the seed of barley only','on the surface of a metal axle','bast 是内层的纤维树皮。'),q('bast',4,1,'The oldest recorded form in English is?','Old English bæst','Old French balada','Greek baros','bast 延续古英语 bæst。')]});
D('bastard',{
  etymology:{origin:'bastard 于13世纪初经古法语 bastard 进入英语，早期指非婚生子女；更早成分词源有争议。现代用于称人时常是粗俗辱骂，某些专业语境也可形容非正宗或不合标准的事物。',prefix:null,root:null,suffix:null,history:[],formationLogic:null,mnemonic:null,note:'称呼个人时具有冒犯性；此处只作词义学习，不宜用来辱骂他人。',source:'Etymonline — https://www.etymonline.com/word/bastard'},
  contexts:[c('bastard.s1','历史 · 法律旧称','The archivist explained that an old register used bastard for a child born to parents who were not married to each other, a term now considered offensive.','档案管理员解释说，旧登记册用 bastard 指父母未婚所生的孩子；这个词如今被认为具有冒犯性。','The archivist / explained / that an old register used bastard / for a child / born to parents who were not married to each other / a term now considered offensive.','explain that；born 过去分词修饰 child；who 引导定语从句。','This carefully framed historical reference gives the outdated legal/social meaning while explicitly noting its offensive status.'),c('bastard.s2','技术 · 非正宗形式','The mechanic rejected the bastard fitting because its thread did not match the standard connector used on the pressure line.','技师拒绝使用那个不合标准的接头，因为它的螺纹与压力管上的标准连接器不匹配。','The mechanic / rejected the bastard fitting / because its thread did not match / the standard connector / used on the pressure line.','because 引导原因从句；used 过去分词修饰 connector。','The mismatched thread shows the nonstandard or irregular technical sense, not the offensive reference to a person.')],
  mistakes:[m('He used bastard as a friendly, universally polite greeting for a new colleague.','He used a polite greeting such as “Good morning” for the new colleague.','称人 bastard 是粗俗且冒犯性的，不是通用友好问候。')],
  quiz:[q('bastard',1,1,'In an old historical record, bastard may refer to?','a child whose parents were not married','a child’s temporary caregiver','a singer with a middle-range voice','该词早期有非婚生子女这一旧称，现多属冒犯。'),q('bastard',2,2,'A “bastard fitting” in technical language may be?','nonstandard or not genuine','a perfectly standard connector','a type of flowering plant','形容物品时可表示不合标准或非正宗。'),q('bastard',3,1,'When used to insult a person, bastard is usually?','offensive and vulgar','a neutral professional title','a polite term of respect','称呼人时是粗俗冒犯的用语。'),q('bastard',4,2,'A fitting with a thread that does not match the standard is?','a nonstandard fitting','a barometric fitting','a bandanna fitting','不匹配标准规格体现物件的非标准义。')]});
D('baste',{
  etymology:{origin:'baste 有不同词源的同形义：缝纫义约1400年经古法语 bastir「建造、缝合」而来，可能与日耳曼语 *bastjan「用韧皮纤维连接」有关；烹饪浇汁义起源不明，可能与古法语 basser「弄湿」有关。',prefix:null,root:null,suffix:null,history:[],formationLogic:null,mnemonic:null,note:'本词条的前两义是烤肉浇汁与粗缝；另有口语「痛打」义但不作为学习重点。',source:'Etymonline — https://www.etymonline.com/word/baste'},
  contexts:[c('baste.s1','烹饪 · 烤制肉类','Every twenty minutes, the cook basted the turkey with hot pan juices so the surface would stay moist during roasting.','厨师每隔二十分钟用热锅汁给火鸡浇一次汁，让烤制时表面保持湿润。','Every twenty minutes / the cook / basted the turkey with hot pan juices / so the surface would stay moist / during roasting.','baste meat with juices；so 引导目的或结果；during + 名词。','The hot pan juices are poured over roasting meat to keep it moist, matching the cooking sense.'),c('baste.s2','缝纫 · 临时粗缝','Before trimming the lining, Marta basted the two fabric panels together with long, loose stitches that she could remove later.','裁剪里布前，玛尔塔用长而松的针脚把两块布料暂时缝在一起，之后可以拆掉。','Before trimming the lining / Marta / basted the two fabric panels together / with long, loose stitches / that she could remove later.','before + 动名词；baste panels together；that 引导定语从句。','Long removable stitches temporarily hold fabric pieces in position, the sewing sense of baste.')],
  mistakes:[m('The cook basted the roast with hot fat, but the instruction meant to attach two pieces of cloth using loose stitches.','The cook basted the cloth panels with loose temporary stitches.','baste 用于缝纫時是粗縫；用熱油淋肉是烹飪義。句子指出的工作是拼合布片，故应使用缝纫义。')],
  quiz:[q('baste',1,1,'When roasting meat, to baste it is to?','spoon hot fat or juices over it','sew its edges with thread','freeze it before serving','烹饪义是用肉汁或热油浇淋肉。'),q('baste',2,2,'In sewing, to baste two pieces is to?','join them temporarily with loose stitches','cut them into tiny strips','dye them blue and dry them','缝纫义是用松长针脚临时缝合。'),q('baste',3,1,'A tailor will usually remove basting stitches?','after the final seams are in place','before placing any fabric on the table','to turn them into hot cooking fat','粗缝针脚是临时固定，之后可拆除。'),q('baste',4,1,'Which context uses the cooking sense?','The cook basted the chicken with pan juices.','The tailor basted the lining to hold it temporarily.','The writer baste the paragraph into a song.','用锅汁淋鸡肉是烹饪义。')]});
D('bathhouse',{
  etymology:{origin:'bathhouse 由 bath「沐浴」与 house「建筑、房屋」组成，17世纪初用于指供公众洗浴或沐浴的建筑；英语 bath 延续古英语 bæð。',prefix:null,root:{text:'bath + house',gloss:'沐浴 + 建筑'},suffix:null,history:[],formationLogic:'bath + house；专门提供沐浴设施的场所。',mnemonic:null,note:'在游泳设施附近，bathhouse 也可指更衣用的附属建筑。',source:'Etymonline — https://www.etymonline.com/word/bathhouse'},
  contexts:[c('bathhouse.s1','公共设施 · 澡堂','The town opened a public bathhouse for residents whose apartments had no reliable hot water or private shower.','镇上为公寓里没有稳定热水或私人淋浴设施的居民开了一家公共澡堂。','The town / opened a public bathhouse / for residents / whose apartments had no reliable hot water / or private shower.','open a facility for someone；whose 引导定语从句；no...or 并列否定。','The facility provides baths and showers to the public, not just a room inside a private home.'),c('bathhouse.s2','游泳 · 更衣场所','After swimming across the lake, the children returned to the bathhouse to change out of their wet clothes.','游过湖后，孩子们回到更衣室换下湿衣服。','After swimming across the lake / the children / returned to the bathhouse / to change out of their wet clothes.','After + 动名词作时间状语；return to；to change 表目的。','The lake-swimming context establishes bathhouse as the changing facility beside a bathing place.')],
  mistakes:[m('The swimmers walked to the bathhouse to change, but the building had no changing space and served only as a distant courthouse.','The swimmers walked to the bathhouse to change in its changing rooms.','游泳场所旁的 bathhouse 可作更衣建筑；法院不是更衣设施。')],
  quiz:[q('bathhouse',1,1,'A public bathhouse is a building where people can?','bathe or wash','borrow legal textbooks','repair a car axle','bathhouse 是公共洗浴建筑。'),q('bathhouse',2,2,'Near a lake, a bathhouse may provide?','a place for swimmers to change clothes','a room for storing artillery','a stage backdrop','水边 bathhouse 可指更衣场所。'),q('bathhouse',3,1,'Which parts form bathhouse?','bath + house','bawl + house','baron + house','bathhouse 是 bath 与 house 的复合词。'),q('bathhouse',4,1,'A bathhouse is most likely a?','facility connected with washing or swimming','type of bird band','musical voice range','该建筑与洗浴或游泳设施有关。')]});
D('bathing',{
  etymology:{origin:'bathing 是动词 bathe 加 -ing 构成的名词或动名词；bathe 延续古英语 baðian「洗浴」，来自与 bath 同族的日耳曼语动词。',prefix:null,root:{text:'bathe',gloss:'洗浴、游泳'},suffix:{text:'-ing',gloss:'构成动作名词或动名词'},history:[],formationLogic:'bathe + -ing；按语境可指游泳休闲或洗澡。',mnemonic:null,note:'英式 go bathing 常指去水中游泳；日常个人洗澡也用 bathing。',source:'Etymonline — https://www.etymonline.com/word/bathe'},
  contexts:[c('bathing.s1','休闲 · 海边游泳','The lifeguard closed the northern cove to bathing after a strong current formed near the rocks.','岩石附近形成强劲水流后，救生员关闭了北侧海湾，禁止人们下水游泳。','The lifeguard / closed the northern cove to bathing / after a strong current formed / near the rocks.','close a place to an activity；after 引导时间状语。','The cove and current identify bathing as recreational swimming in natural water.'),c('bathing.s2','护理 · 沐浴清洁','Gentle bathing with lukewarm water helped remove the ointment without irritating the child’s skin.','用温水轻柔沐浴有助于洗掉药膏，同时不刺激孩子的皮肤。','Gentle bathing with lukewarm water / helped remove the ointment / without irritating the child’s skin.','help + 动词原形；without + 动名词。','Washing with water to clean the body or skin is the personal-washing sense of bathing.')],
  mistakes:[m('The council closed the cove to bathing, but invited visitors to swim freely there during the dangerous current.','The council closed the cove to bathing and asked visitors not to swim during the dangerous current.','close a place to bathing 表示禁止在其中游泳；开放游泳与这一限制相矛盾。')],
  quiz:[q('bathing',1,1,'A sign “No bathing” at a beach prohibits?','swimming in the water','walking along the shore','reading a printed guide','bathing 可表示在海、湖或泳池游泳休闲。'),q('bathing',2,2,'Gentle bathing with soap and water is?','washing the body','playing a brass instrument','tying hay into a bale','bathing 的另一义是沐浴、洗澡。'),q('bathing',3,1,'In British English, “go bathing” often means?','go swimming','go bankrupted','go to conduct a band','英式 go bathing 常指去水中游泳。'),q('bathing',4,2,'Which sentence uses bathing in the washing sense?','The nurse assisted with the patient’s bathing.','The children went bathing in the lake.','The council banned bathing in the cove.','帮助病人清洁身体是沐浴义。')]});
D('battleship',{
  etymology:{origin:'battleship 由 battle「战斗」与 ship「舰船」组成，18世纪末开始用于指配有重装甲与大口径舰炮、承担海战主力任务的大型军舰。',prefix:null,root:{text:'battle + ship',gloss:'战斗 + 舰船'},suffix:null,history:[],formationLogic:'battle + ship；承担主力海战任务的重型军舰。',mnemonic:null,note:'battleship 是历史上的主力舰类别；现代海军主力舰型已发生变化。',source:'Etymonline — https://www.etymonline.com/word/battleship'},
  contexts:[c('battleship.s1','军事 · 海军舰艇','The museum’s battleship had thick armour around its gun turrets, and visitors could walk along the protected deck during guided tours.','博物馆里的战列舰在炮塔周围装有厚重装甲，游客可在导览期间沿着受保护的甲板行走。','The museum’s battleship / had thick armour around its gun turrets / and visitors / could walk along the protected deck / during guided tours.','have armour around；and 连接并列分句；could walk 表示许可。','Heavy armour and large gun turrets are defining features of a battleship.'),c('battleship.s1','历史 · 舰炮作战','In the naval exercise, the battleship fired its main guns at a target raft while escort vessels stayed outside the marked range.','海军演习中，战列舰向目标浮筏发射主炮，而护航舰留在标示射程之外。','In the naval exercise / the battleship / fired its main guns at a target raft / while escort vessels stayed / outside the marked range.','fire guns at a target；while 表对照；stay outside。','The main-gun role and escort distinction match the capital warship sense.')],
  mistakes:[m('The navy classified a lightly armed fishing boat with no armour as a battleship because it carried a net.','The navy classified a heavily armoured warship with large guns as a battleship.','battleship 是重装甲、配大型舰炮的战舰；渔船和渔网不符合舰艇类型。')],
  quiz:[q('battleship',1,1,'A battleship is a?','large heavily armoured warship with big guns','small civilian boat used to carry fruit','public building for taking baths','battleship 指配有重装甲和大口径舰炮的大型战舰。'),q('battleship',2,1,'Which feature would a battleship likely have?','armoured gun turrets','a basket woven from willow','a stage curtain with painted mountains','战列舰有装甲和舰炮。'),q('battleship',3,1,'Battleship is formed from?','battle + ship','bathing + ship','beaver + ship','它是 battle 与 ship 的复合词。'),q('battleship',4,1,'A battleship’s main purpose historically was?','fighting major naval battles','providing short-term childcare','teaching basket weaving','战列舰曾承担海战主力任务。')]});
D('baulk',{
  etymology:{origin:'baulk 是 balk 的英式拼写变体；词族可追溯至古英语 balca「脊、梁、障碍」，来自日耳曼语，先有障碍物义，后有犹豫不前的动词义。',prefix:null,root:null,suffix:null,history:[],formationLogic:null,mnemonic:null,note:'英式 baulk 与 balk 意义相同；名词较少见，动词常用 baulk at。',source:'Etymonline — https://www.etymonline.com/word/balk'},
  contexts:[c('baulk.s1','木工 · 横梁','The carpenter selected a seasoned baulk of oak from the timber yard and marked the length needed for the roof frame.','木匠从木料场挑了一根干透的橡木方梁，并标出屋顶框架所需的长度。','The carpenter / selected a seasoned baulk of oak / from the timber yard / and marked the length / needed for the roof frame.','a baulk of oak 指一根粗木梁；并列谓语 selected、marked；needed 修饰 length。','A squared timber beam is the less common noun sense recorded in the source entry.'),c('baulk.s2','反应 · 犹豫拒绝','The horse baulked at the dark tunnel, so the handler walked ahead with a lantern until it began to follow.','马在昏暗隧道前畏缩不前，于是驯马师提着灯走在前面，直到它开始跟上。','The horse / baulked at the dark tunnel / so the handler / walked ahead with a lantern / until it began to follow.','baulk at + 名词；so 表结果；until 引导时间从句。','The horse’s hesitation and refusal to proceed show the verb sense.'),c('baulk.s2','交易 · 不愿接受','She baulked at the unusually high repair estimate and asked another garage to inspect the damaged axle.','她不愿接受过高的维修报价，于是请另一家修车厂检查损坏的车轴。','She / baulked at the unusually high repair estimate / and asked another garage / to inspect the damaged axle.','baulk at 表示犹豫或拒绝接受；ask someone to do。','The estimate is an offer the customer hesitates to accept, an extended use of the verb.')],
  mistakes:[m('The horse baulked at the familiar, open gate and immediately crossed it without stopping or resistance.','The horse baulked at the unfamiliar, narrow gate and refused to cross.','baulk 表示突然停下、畏缩或拒绝接受；毫无停顿地通过与其相反。')],
  quiz:[q('baulk',1,1,'A baulk of timber can be?','a roughly squared wooden beam','a slow romantic song','a type of bacteria','baulk 的名词义之一是木方梁。'),q('baulk',2,2,'A horse that baulks at a tunnel?','stops and refuses to go in','runs through eagerly','repairs the tunnel wall','baulk 作动词表示突然停下或畏缩。'),q('baulk',3,2,'If a buyer baulks at a price, the buyer?','hesitates or refuses to accept it','pays it immediately without concern','measures it with a ruler','baulk at a price 表示不愿接受或对其犹豫。'),q('baulk',4,1,'Which spelling has the same meaning?','balk','back','bake','balk 是 baulk 的另一种拼法。')]});
D('bawl',{
  etymology:{origin:'bawl 约15世纪出现，可能是模仿大声喊叫或哭泣的拟声词；词源辞典认为其来源不确定，不进一步推测更早词根。',prefix:null,root:null,suffix:null,history:[],formationLogic:null,mnemonic:null,note:'可作动词「大声喊、嚎哭」，也可作名词指喊声或哭声；与 ball 同音但拼写不同。',source:'Etymonline — https://www.etymonline.com/word/bawl'},
  contexts:[c('bawl.s1','情绪 · 大声哭喊','The toddler began to bawl when the noisy vacuum started, so his father carried him to the quiet bedroom.','吸尘器一启动，幼儿就开始嚎哭，于是父亲把他抱到安静的卧室。','The toddler / began to bawl / when the noisy vacuum started / so his father / carried him to the quiet bedroom.','begin to do；when 引导时间从句；so 连接结果。','The child’s loud crying at a startling noise fits the verb sense.'),c('bawl.s2','运动 · 大声喊声','A single bawl from the touchline stopped the players just before they ran into the referee.','边线传来一声大喊，球员们在撞上裁判前停了下来。','A single bawl from the touchline / stopped the players / just before they ran into the referee.','a bawl from someone；stop + 宾语；before 引导时间状语。','One loud shout rather than the act of crying is the noun sense of bawl.')],
  mistakes:[m('The child whispered so softly that nobody could hear him, but his parents described the sound as a loud bawl.','The child shouted so loudly that everyone could hear him, producing a loud bawl.','bawl 是大声叫喊或哭声；低声耳语不符合其音量特征。')],
  quiz:[q('bawl',1,1,'A child who bawls is?','shouting or crying very loudly','speaking in a barely audible whisper','reading a guidebook silently','bawl 作动词指大声喊叫或嚎哭。'),q('bawl',2,2,'A bawl from the sideline is?','a loud shout','a small woven basket','a type of mild weather','名词 bawl 可指一声大喊或哭声。'),q('bawl',3,1,'Which word is pronounced the same but means a round object?','ball','bale','bail','bawl 与 ball 同音，ball 意为球。'),q('bawl',4,1,'Which sentence clearly uses bawl as a verb?','The baby bawled when the lights came on.','A bawl echoed across the field.','The ball rolled under the chair.','baby bawled 描述大声哭喊，bawl 作动词。')]});
D('bayonet',{
  etymology:{origin:'bayonet 于17世纪初经法语 baïonnette 进入英语，最初是短剑；后来指装在枪口上的刺刀。名称据说源自法国巴约讷城，也可能来自古法语 bayon「弩箭」，起源未定。',prefix:null,root:null,suffix:null,history:[],formationLogic:null,mnemonic:null,note:'bayonet 可作名词指刺刀，也可作动词表示用刺刀攻击；此词条以名词义为主。',source:'Etymonline — https://www.etymonline.com/word/bayonet'},
  contexts:[c('bayonet.s1','军事 · 步枪配件','The museum guide showed how a bayonet could be fixed to the rifle’s muzzle for close combat, then removed before the weapon was stored.','博物馆讲解员演示了如何把刺刀固定在步枪枪口上用于近战，并在收存武器前卸下。','The museum guide / showed / how a bayonet could be fixed to the rifle’s muzzle / for close combat / then removed / before the weapon was stored.','show how；被动 could be fixed；then 表动作顺序。','The blade attaches to the muzzle of a rifle and is used in close fighting, the standard noun sense.'),c('bayonet.s1','历史 · 近战武器','The infantryman carried a bayonet on his belt, although the battle plan called for him to keep it sheathed unless the enemy approached.','步兵把刺刀挂在腰带上，不过作战计划要求除非敌人靠近，否则不要拔出。','The infantryman / carried a bayonet on his belt / although the battle plan required him / to keep it sheathed / unless the enemy approached.','although 引导让步；require someone to do；unless 表条件。','The blade is a carried weapon reserved for close combat rather than a tool for ordinary work.')],
  mistakes:[m('The soldier fixed a bayonet to the rifle’s stock, far from the muzzle, so it could be used as a close-combat blade.','The soldier fixed a bayonet to the rifle’s muzzle so it could be used as a close-combat blade.','刺刀安装在枪口端；固定在枪托上无法发挥刺击用途。')],
  quiz:[q('bayonet',1,1,'A bayonet is a blade attached to a?','rifle for close fighting','basket for carrying fruit','barometer for measuring pressure','bayonet 是安装在步枪上的近战刺刀。'),q('bayonet',2,1,'Where is a bayonet fixed?','at the muzzle of a rifle','under the heel of a boot','behind a theatre curtain','刺刀固定在枪口前端。'),q('bayonet',3,1,'A bayonet is designed mainly for?','close combat','weaving baskets','recording weather data','刺刀供近距离搏斗使用。'),q('bayonet',4,1,'The proposed name origin may refer to?','Bayonne, a city in France','a village in ancient Babylon','the French word for a guidebook','bayonet 据说可能以法国巴约讷命名，但词源未定。')]});
D('beaded',{
  etymology:{origin:'beaded 由 bead 加 -ed 构成，作形容词表示饰有珠子的，也可描述排列成珠状小圆点的物体；bead 原指祈祷珠，后泛指小珠。',prefix:null,root:{text:'bead',gloss:'小珠、珠子'},suffix:{text:'-ed',gloss:'表示具有某物或呈现某状态'},history:[],formationLogic:'bead + -ed；由珠子派生出饰珠或珠状的形容词。',mnemonic:null,note:'beaded 可指装饰珠子，也可形容水珠排成一串。',source:'Etymonline — https://www.etymonline.com/word/beaded'},
  contexts:[c('beaded.s1','服饰 · 珠饰','The dancer wore a beaded jacket whose small glass ornaments caught the stage lights whenever she turned.','舞者穿着一件饰有珠子的夹克，每次转身时，小玻璃珠都会映出舞台灯光。','The dancer / wore a beaded jacket / whose small glass ornaments / caught the stage lights / whenever she turned.','wear + 衣物；whose 引导定语从句；whenever 表示每当。','Glass ornaments attached to the jacket establish the decoration sense.'),c('beaded.s2','天气 · 水珠形态','By dawn, a line of beaded droplets clung to the spiderweb, each one shining above the wet grass.','到黎明时，一串珠状水滴挂在蜘蛛网上，每一滴都在湿草上方闪着光。','By dawn / a line of beaded droplets / clung to the spiderweb / each one shining / above the wet grass.','a line of；cling to；each one shining 为独立主格补充。','The tiny round droplets form bead-like spheres, the second adjective sense.')],
  mistakes:[m('The jacket was described as beaded, although its surface was completely plain and had no beads or bead-like details.','The jacket was described as plain, with no beads or bead-like details.','beaded 必须有珠饰或珠状外观；完全光滑且没有珠子不符合该形容词。')],
  quiz:[q('beaded',1,1,'A beaded jacket is decorated with?','small beads','large steel wheels','a painted stage backdrop only','beaded 的第一义是饰以小珠。'),q('beaded',2,2,'Beaded droplets look like?','small round beads lined up together','long flat ribbons','square sheets of paper','第二义是呈珠状或挂成一串的小圆滴。'),q('beaded',3,1,'Which sentence uses the decoration sense?','She wore a beaded purse to the dance.','A beaded line of dew shone on the web.','The barley was harvested.','手袋上装饰珠子，是饰珠义。'),q('beaded',4,1,'Which base word forms beaded?','bead','beau','beaver','bead + -ed 构成 beaded。')]});
D('beaming',{
  etymology:{origin:'beaming 是 beam 加 -ing 构成的现在分词和形容词；beam 延续古英语 bēam「树木、梁」，之后引申为光束，动词「发光」再引申为笑容灿烂。',prefix:null,root:{text:'beam',gloss:'光束；发出光'},suffix:{text:'-ing',gloss:'构成分词或描述状态的形容词'},history:[],formationLogic:'beam + -ing；表示发光或笑容明亮。',mnemonic:null,note:'beaming 可形容满面笑容，也可描述明亮的光。',source:'Etymonline — https://www.etymonline.com/word/beaming'},
  contexts:[c('beaming.s1','情绪 · 灿烂笑容','The student was beaming after her research poster won first prize, and she thanked every lab partner who had helped her.','研究海报获一等奖后，学生笑容满面，并向帮助过她的每位实验室伙伴致谢。','The student / was beaming / after her research poster won first prize / and she thanked / every lab partner / who had helped her.','beaming 作表语形容词；after 引导时间从句；who 引导定语从句。','The prize and thanks for teamwork provide a joyful reason for a broad, bright smile.'),c('beaming.s2','光线 · 明亮发光','A beaming searchlight swept across the harbor, illuminating the boats and the wet stone wall.','一道明亮的探照灯扫过港口，照亮了船只和潮湿的石墙。','A beaming searchlight / swept across the harbor / illuminating the boats / and the wet stone wall.','sweep across；illuminating 分词表示伴随结果。','The searchlight emits a strong, bright beam, showing the literal shining sense.')],
  mistakes:[m('He was beaming with delight but wore a deeply miserable, tearful expression throughout the celebration.','He was beaming with delight and wore a broad, joyful smile throughout the celebration.','beaming with delight 表示笑容灿烂；悲伤流泪的表情与之不符。')],
  quiz:[q('beaming',1,1,'A beaming student after winning a prize is?','smiling broadly with happiness','crying in disappointment','standing in complete darkness','beaming 常形容喜悦、笑容满面。'),q('beaming',2,2,'A beaming searchlight is?','shining brightly','turned off and unlit','woven from willow strips','beaming 也可描述明亮的光。'),q('beaming',3,1,'Which phrase is natural?','a beaming smile','a beaming bankruptcy','a beaming bathhouse','beaming smile 是常见搭配。'),q('beaming',4,1,'The figurative smile sense is related to which image?','a bright beam of light','a heavy naval gun','a basket tied with rope','beam 先指光束；笑容 beaming 比喻明亮灿烂。')]});
D('beater',{
  etymology:{origin:'beater 由动词 beat 加施事后缀 -er 构成，泛指用来敲打、搅拌或拍打的工具；狩猎语境中特指拍打灌木、把猎物赶出的人员。',prefix:null,root:{text:'beat',gloss:'敲打、拍打'},suffix:{text:'-er',gloss:'实施动作的工具或人'},history:[],formationLogic:'beat + -er；指拍打工具或执行拍打的人。',mnemonic:null,note:'口语还可指破旧车；本词条重点是源词条收录的工具和狩猎义。',source:'Etymonline — https://www.etymonline.com/word/beater'},
  contexts:[c('beater.s1','厨房 · 搅打工具','She used an electric beater to whip the eggs until the mixture became pale, thick, and full of air.','她用电动搅拌器把鸡蛋打到颜色变浅、质地浓稠且充满空气。','She / used an electric beater / to whip the eggs / until the mixture became pale, thick, and full of air.','use a tool to do；until 引导时间状语；became 后接形容词并列。','The appliance beats eggs to incorporate air, illustrating beater as a mixing tool.'),c('beater.s2','狩猎 · 赶出猎物','The beaters moved through the brush in a line, driving the hidden pheasants toward the open field where observers waited.','赶猎人员排成一线穿过灌木丛，把藏起来的野鸡赶向观察者等候的空地。','The beaters / moved through the brush in a line / driving the hidden pheasants / toward the open field / where observers waited.','move in a line；driving 分词表示目的或伴随；where 引导定语从句。','People beating bushes to flush animals toward hunters are beaters in the hunting sense.')],
  mistakes:[m('The beaters hid quietly at the edge of the field and frightened no animals out of the bushes.','The beaters moved through the bushes to drive the birds toward the waiting hunters.','狩猎义的 beater 是通过拍打灌木把动物赶出来的人；静静躲着不驱赶猎物不符合定义。')],
  quiz:[q('beater',1,1,'A kitchen beater is used to?','mix or whip ingredients such as eggs','measure a ship’s armour','decorate a stage curtain','beater 可指搅拌或拍打用具。'),q('beater',2,2,'In a hunt, beaters move through bushes to?','flush animals toward the hunters','cook the animals before a hunt','repair the hunters’ rifles','狩猎中 beater 通过拍打灌木赶出猎物。'),q('beater',3,1,'Which task fits a hand beater?','whipping eggs into a foamy mixture','barricading a flooded street','weaving a reed basket','打蛋器可把鸡蛋搅打起泡。'),q('beater',4,2,'A person moving pheasants out of cover for hunters is a?','beater','balloonist','banker','将猎物赶出藏身处的人叫 beater。')]});
D('beau',{
  etymology:{origin:'beau 于17世纪借自法语 beau「美的、英俊的」，原是形容词，之后名词化为追求或陪伴女士的男友、情郎；法语形式来自古法语 bel 与拉丁语 bellus「美好」。',prefix:null,root:{text:'Latin bellus',gloss:'美好、英俊'},suffix:null,history:[],formationLogic:null,mnemonic:null,note:'复数可写 beaus 或 beaux；现代语境常显得旧式。',source:'Etymonline — https://www.etymonline.com/word/beau'},
  contexts:[c('beau.s1','文学 · 恋爱关系','In the novel, Clara’s beau waited outside the opera house with flowers after she finished her performance.','小说中，克拉拉演出结束后，她的男友捧着鲜花在歌剧院外等她。','In the novel / Clara’s beau / waited outside the opera house / with flowers / after she finished her performance.','wait outside；with 表伴随；after 引导时间从句。','A romantic partner waiting to meet Clara after her show matches the older noun sense of beau.'),c('beau.s1','旧式表达 · 求爱者','Her grandmother recalled that her first beau used to bring a book whenever he called at the family home.','她的祖母回忆说，她的第一位追求者每次登门时都会带一本书。','Her grandmother / recalled / that her first beau used to bring a book / whenever he called / at the family home.','recall that；used to 表过去习惯；whenever 引导时间从句。','The courtship visits and romantic attention show beau as a suitor or boyfriend.')],
  mistakes:[m('She introduced her beau as the woman who was courting him and bringing him flowers.','She introduced her beau as the man who was courting her and bringing her flowers.','beau 的词条义是追求或陪伴女士的男性恋人；原句将性别关系倒置。')],
  quiz:[q('beau',1,1,'A woman’s beau is traditionally her?','male suitor or boyfriend','female employer','male singing voice','beau 指女士的男友或追求者。'),q('beau',2,1,'Which scene best fits beau?','a suitor waits outside the theatre with flowers','a barometer measures pressure in a storm','a child is supervised for one hour','送花等候的追求者符合 beau 的旧式恋爱义。'),q('beau',3,1,'The English word was borrowed from French for?','handsome or beautiful','woven inner bark','a burst of artillery','beau 由法语 beau「美的、英俊的」名词化。'),q('beau',4,1,'Which plural spelling is accepted?','beaux','beausen','beaues','beaux 是 beau 的一个常见复数形式。')]});
D('beaver',{
  etymology:{origin:'beaver 延续古英语 beofor，来自原始日耳曼语 *bebruz，并与古诺尔斯语、德语等同源；更远来源可能与「棕色」有关，但本词条不把该重建当作确定结论。',prefix:null,root:null,suffix:null,history:[],formationLogic:null,mnemonic:null,note:'除动物外，beaver 也可指海狸皮毛；部分俚语义粗俗，不作教学例句。',source:'Etymonline — https://www.etymonline.com/word/beaver'},
  contexts:[c('beaver.s1','野生动物 · 河岸','A beaver dragged willow branches into the pond and packed mud around its dam before the water level began to rise.','一只海狸把柳枝拖进池塘，在水位开始上涨前把泥巴填到水坝周围。','A beaver / dragged willow branches into the pond / and packed mud around its dam / before the water level began to rise.','并列谓语 dragged、packed；before 引导时间从句。','The animal builds with branches and mud in water, identifying the semiaquatic rodent.'),c('beaver.s2','制品 · 海狸皮','The historical display showed a beaver hat beside a note explaining how fur traders once used the animal’s thick pelt.','历史展览在海狸皮帽旁放了一块说明牌，解释过去毛皮商如何利用这种动物厚实的皮毛。','The historical display / showed a beaver hat / beside a note / explaining how fur traders once used the animal’s thick pelt.','beside a note；explaining 分词修饰 note；how 引导宾语从句。','The hat made from the animal’s dense fur illustrates beaver as the pelt or fur material.')],
  mistakes:[m('The wildlife guide identified the beaver as a fish with scales that lives and breathes only underwater.','The wildlife guide identified the beaver as a furry rodent that lives near water and builds dams.','beaver 是有毛的啮齿动物，不是有鳞鱼；筑坝和水边生活支持正确分类。')],
  quiz:[q('beaver',1,1,'A beaver is a?','large rodent that lives near water and builds dams','small insect that spins a web','fish with scales and gills','beaver 是生活在水边、筑坝的大型啮齿动物。'),q('beaver',2,2,'A beaver hat is made from?','the animal’s thick fur','a piece of basalt','a bandanna folded into a hat','beaver 也可指海狸皮毛，常见历史用途包括制帽。'),q('beaver',3,1,'Which animal is known for building dams?','beaver','baboon','badger','海狸以修筑水坝著称。'),q('beaver',4,1,'The source traces beaver to which early English form?','Old English beofor','Old English baðian','Old French baroque','beaver 延续古英语 beofor。')]});
D('becoming',{
  etymology:{origin:'becoming 由 become 加 -ing 构成，先可作动名词或现在分词，后发展出形容词义「得体、相称、使人好看」；形容词用法常修饰衣着、态度或行为。',prefix:null,root:{text:'become',gloss:'变得、适合'},suffix:{text:'-ing',gloss:'构成分词及相关形容词'},history:[],formationLogic:'become + -ing；becoming 的形容词义指与人或场合相称。',mnemonic:null,note:'形容词 becoming 与动词 become「变成」需按句法区分。',source:'Etymonline — https://www.etymonline.com/word/becoming'},
  contexts:[c('becoming.s1','礼仪 · 举止得体','The chairperson’s becoming restraint kept the tense hearing orderly, even when two witnesses began to argue.','主席得体的克制让紧张的听证会保持秩序，即使两名证人开始争论也不例外。','The chairperson’s becoming restraint / kept the tense hearing orderly / even when two witnesses began to argue.','keep + 宾语 + 形容词补语；even when 引导让步从句。','Restraint that is suitable and polite in a tense public hearing illustrates the “appropriate” sense.'),c('becoming.s2','服饰 · 衬托外貌','The tailor suggested a becoming shade of blue that brought out the customer’s eyes without overpowering the simple cut.','裁缝建议选一种衬托顾客眼睛的蓝色，同时不会压过简洁的剪裁。','The tailor / suggested a becoming shade of blue / that brought out the customer’s eyes / without overpowering the simple cut.','suggest a shade；that 引导定语从句；without + 动名词。','The colour enhances the wearer’s appearance and suits the garment, the “flattering” sense.')],
  mistakes:[m('The tailor chose a becoming colour that made the customer look ill and clashed with every part of the outfit.','The tailor chose a becoming colour that suited the customer and complemented the outfit.','becoming 描述得体或衬托人的颜色；显得病态且处处冲突与其相反。')],
  quiz:[q('becoming',1,1,'A becoming manner in a formal meeting is?','appropriate and polite','rude and disruptive','unrelated to the occasion','becoming 可表示行为得体、合宜。'),q('becoming',2,2,'A becoming dress or colour?','makes someone look attractive','makes the outfit unsuitable for the wearer','is always made of woven reeds','becoming 的另一义是衬托人的外表。'),q('becoming',3,1,'Which sentence uses becoming as an adjective?','She chose a becoming jacket for the ceremony.','She is becoming a doctor next year.','They became tired after the walk.','修饰 jacket 的 becoming 是形容词“好看的、相称的”。'),q('becoming',4,2,'A becoming shade of blue would likely?','complement the wearer’s appearance','make the wearer look ill','refer to a process of changing careers','becoming 色彩应衬托穿着者。')]});
D('bedcover',{
  etymology:{origin:'bedcover 由 bed「床」与 cover「覆盖物」组成的复合名词，指铺在床上、盖住被褥或作装饰的罩布；cover 延续古法语 couvrir 与拉丁语 cooperire「覆盖」。',prefix:null,root:{text:'bed + cover',gloss:'床 + 覆盖物'},suffix:null,history:[],formationLogic:'bed + cover；覆盖床面的布料。',mnemonic:null,note:'bedcover 是床上覆盖层；duvet 是保暖被芯，两者用途不同。',source:'Etymonline — https://www.etymonline.com/word/bedcover'},
  contexts:[c('bedcover.s1','家居 · 床罩','Before the guests arrived, Mei spread a clean bedcover over the quilt and smoothed the corners beneath the pillows.','客人到来前，梅把干净床罩铺在被子上，并把枕头下面的边角抚平。','Before the guests arrived / Mei / spread a clean bedcover over the quilt / and smoothed the corners / beneath the pillows.','spread a cover over；并列谓语 spread、smoothed；before 引导时间。','The cloth lies over the quilt as a protective or decorative bed layer.'),c('bedcover.s1','居家 · 洗涤床罩','The cotton bedcover was removed for washing while the heavier duvet stayed on the bed to keep the room warm.','棉床罩被取下来清洗，而较厚的羽绒被仍留在床上保暖。','The cotton bedcover / was removed for washing / while the heavier duvet stayed on the bed / to keep the room warm.','被动 was removed；while 表对比；to keep 表目的。','The contrast with the insulating duvet shows bedcover is the outer covering layer.')],
  mistakes:[m('She removed the bedcover for washing, then used it as the duvet’s inner filling to keep warm overnight.','She removed the bedcover for washing, while the duvet remained as the warm inner bedding.','bedcover 是罩在外面的布层，duvet 是保暖被芯；不能把二者角色混淆。')],
  quiz:[q('bedcover',1,1,'A bedcover is?','cloth spread over a bed, often for protection or decoration','a metal bar connecting two wheels','a type of slow song','bedcover 指铺在床上的覆盖布。'),q('bedcover',2,1,'Which item is usually the insulating duvet rather than the bedcover?','the thick inner bedding','the decorative cloth on top','a woven chair seat','duvet 是保暖被芯，bedcover 是外面的床罩。'),q('bedcover',3,1,'Which phrase is natural?','a cotton bedcover','a cotton bedcovering room','a bedcover on the floor of a ballroom','cotton bedcover 是自然搭配。'),q('bedcover',4,1,'Bedcover is formed from?','bed + cover','bedeck + cover','beaver + cove','bedcover 是 bed 与 cover 的复合词。')]});
D('bedeck',{
  etymology:{origin:'bedeck 约16世纪出现，由 be- 与 deck「覆盖、装饰」构成；deck 作为动词与日耳曼语表示覆盖的词同源。现代 bedeck 常带「挂满、盛装点缀」的意味。',prefix:{text:'be-',gloss:'使处于某状态或施加动作'},root:{text:'deck',gloss:'装饰、覆盖'},suffix:null,history:[],formationLogic:'be- + deck；用饰物覆盖或装点。',mnemonic:null,note:'常见结构 bedeck A with B，表示用旗帜、鲜花或珠宝装点某处或某人。',source:'Etymonline — https://www.etymonline.com/word/bedeck'},
  contexts:[c('bedeck.s1','节庆 · 装饰街道','Volunteers bedecked the market square with lanterns and winter greenery before the annual evening festival.','年度夜间节庆前，志愿者用灯笼和冬青装点了集市广场。','Volunteers / bedecked the market square with lanterns and winter greenery / before the annual evening festival.','bedeck A with B；before 引导时间状语。','Lanterns and greenery are decorations covering the square, matching bedeck’s adornment sense.'),c('bedeck.s1','典礼 · 花饰礼堂','The organizers bedecked the hall with paper flowers, coloured ribbons, and banners made by local schoolchildren.','组织者用纸花、彩带和当地学童制作的横幅装点礼堂。','The organizers / bedecked the hall with paper flowers / coloured ribbons / and banners / made by local schoolchildren.','bedeck the hall with；made 过去分词修饰 banners。','The hall is visibly adorned with several decorative objects.')],
  mistakes:[m('The organizers bedecked the hall by stripping off every banner, flower, and ribbon until its walls were bare.','The organizers bedecked the hall with banners, flowers, and ribbons.','bedeck 意为装饰、打扮；移走装饰物并使房间空荡与其含义相反。')],
  quiz:[q('bedeck',1,1,'To bedeck a hall with flowers is to?','decorate it with flowers','remove all decorations from it','measure its air pressure','bedeck 表示用鲜花等装点。'),q('bedeck',2,1,'Which pattern is natural?','bedeck the square with lanterns','bedeck the square from lanterns to','bedeck with the square at lanterns','常见结构是 bedeck + 地点/物体 + with + 装饰物。'),q('bedeck',3,1,'What might people bedeck for a festival?','a hall with ribbons and banners','an axle with a legal verdict','a barley field with a courtroom','节庆中会用彩带、横幅装点礼堂。'),q('bedeck',4,1,'Which verb is closest in meaning?','adorn','barricade','bawl','adorn 表示装饰，接近 bedeck。')]});
D('bedlam',{
  etymology:{origin:'bedlam 由 Bethlehem 的口语缩读而来，指伦敦圣玛丽伯利恒医院；该院后来成为收治精神疾病患者的机构，17世纪中期 Bedlam 引申为喧闹混乱的场面。',prefix:null,root:{text:'Bethlehem',gloss:'伯利恒；伦敦伯利恒医院名称来源'},suffix:null,history:[],formationLogic:'Bethlehem 的口语缩读，由专名转为混乱场所的普通名词。',mnemonic:null,note:'bedlam 指混乱喧闹的局面；源头涉及历史精神病院，避免把现代患者当作贬义比喻。',source:'Etymonline — https://www.etymonline.com/word/bedlam'},
  contexts:[c('bedlam.s1','活动现场 · 喧闹混乱','When the station announced that every train was delayed, the crowded platform turned into bedlam as passengers rushed to different exits.','车站宣布所有列车都延误后，拥挤的站台顿时乱作一团，乘客纷纷冲向不同出口。','When the station announced that every train was delayed / the crowded platform / turned into bedlam / as passengers rushed to different exits.','When 引导时间从句；turn into；as 表同时发生的混乱场景。','Many passengers moving noisily in different directions create the chaotic situation sense.'),c('bedlam.s1','办公室 · 突发混乱','The office was bedlam after the fire alarm sounded, with staff collecting coats while security cleared the corridors.','火警响起后，办公室一片混乱，员工忙着拿外套，保安则清理走廊。','The office / was bedlam / after the fire alarm sounded / with staff collecting coats / while security cleared the corridors.','be bedlam 作表语；with + 名词 + 分词结构；while 表同时。','The sudden alarm, competing actions, and disorder establish a noisy confusion rather than a psychiatric diagnosis.')],
  mistakes:[m('The evacuation proceeded in calm, orderly silence, and the staff accurately described the scene as bedlam.','The evacuation proceeded in calm, orderly silence, and the staff described it as orderly.','bedlam 指喧闹混乱；有序安静的疏散与该词相反。')],
  quiz:[q('bedlam',1,1,'A station in bedlam is?','noisy and confused','quiet and perfectly orderly','covered in a layer of woven reeds','bedlam 指喧闹混乱的场面。'),q('bedlam',2,1,'The word bedlam came from a shortened name for?','a London hospital called Saint Mary of Bethlehem','a French town where bayonets were made','a German guidebook publisher','bedlam 源于伦敦圣玛丽伯利恒医院名称的缩读。'),q('bedlam',3,1,'Which event could turn a platform into bedlam?','many delayed passengers rushing in different directions','one person quietly reading a map','a train arriving exactly on schedule','嘈杂、无序的人群活动符合 bedlam。'),q('bedlam',4,1,'Which word is closest to bedlam in this source sense?','chaos','composure','barley','chaos 表示混乱，接近 bedlam。')]});
})(typeof window !== 'undefined' ? window : globalThis);
